  "Alkalmazás mentése fájlba": "Зберегти застосунок у файл",
  "Az alkalmazást egyetlen fájlba mentheted, és internet nélkül telepítheted egy másik Android telefonra. A saját adataid nincsenek benne: azokat a Teljes mentés viszi át, titkosítva.": "Застосунок можна зберегти в один файл і встановити без інтернету на інший телефон Android. Ваших власних даних у ньому немає: їх переносить Повна резервна копія, у зашифрованому вигляді.",
