  "Tartalom mentése fájlba": "Зберегти вміст у файл",
  "Ezen a telefonon még nincs letöltött tartalom.": "На цьому телефоні ще немає завантаженого вмісту.",
  "Tartalom betöltése fájlból": "Завантажити вміст із файлу",
