  "Másold át a fájlokat a másik telefonra: SD-kártyán, USB-kábellel, pendrive-on vagy Bluetooth-on.": "Скопіюйте файли на інший телефон: на SD-картці, через USB-кабель, на флешці або через Bluetooth.",
  "A másik telefonon nyisd meg az .apk fájlt a Fájlok alkalmazásban, és koppints a Telepítés gombra. Ha a telefon kéri, egyszer engedélyezd az „Ismeretlen alkalmazások telepítése” beállítást annak az alkalmazásnak, amellyel a fájlt megnyitottad.": "На іншому телефоні відкрийте файл .apk у застосунку «Файли» й торкніться «Встановити». Якщо телефон попросить, один раз дозвольте «Встановлення невідомих застосунків» для застосунку, яким ви відкрили файл.",
  "Indítsd el az alkalmazást, nyisd meg a Beállítások, Adatok és mentés részt, koppints a „Tartalom betöltése fájlból” gombra, és válaszd ki a .pptartalom fájlt.": "Запустіть застосунок, відкрийте Налаштування, Дані та резервна копія, торкніться «Завантажити вміст із файлу» й виберіть файл .pptartalom.",
  "Végül a saját adataidat a Teljes mentés fájljából töltsd vissza a Visszatöltés gombbal, a mentési kulcsoddal.": "Наостанок відновіть свої дані з файлу Повної резервної копії кнопкою «Відновити», використовуючи ключ резервної копії.",
  "Betöltés folyamatban": "Завантаження",
