  "Ez a fordítás nem tartalmazza a halványan jelölt könyveket. Ott ennek a szövege olvasható: {ford}.": "У цьому перекладі немає блідих книг. Там замість нього читається цей текст: {ford}.",
  "Ez a fordítás nem tartalmazza ezt a könyvet. Itt ennek a szövege olvasható: {ford}.": "У цьому перекладі немає цієї книги. Тут замість нього читається цей текст: {ford}.",
