  // ===== 2026-11-02 Gerah escrow + weekly goal (owner TG 33434/33435, decision A TG 1322, card 8ed3c59e; the daily item is the signed wording) =====
  "Napi Bibliaolvasás, heti céllal. Minden nap, amikor eléred a napra beállított olvasási célodat, Gerah kerül letétbe a cél hossza szerint: legalább 10 perces cél után 1, legalább 20 perces után 2, legalább 30 perces után 3; az 5 perces cél után nem jár. Naponta legfeljebb 3 gerah. A letét akkor kerül a tárcádba, ha 7 egymást követő napon eléred a napi célodat. Ha egy nap kimarad, a letét elvész, és a hét nap elölről indul. A Gerah-t a PrepperPapa alkalmazás tárcája tárolja: a Wordlightban végzett olvasásért akkor jár, ha nálad telepítve van a PrepperPapa alkalmazás. A reggeli ébresztős felolvasás is beleszámít.": "Щоденне читання Біблії з тижневою метою. Кожного дня, коли ти досягаєш мети читання, встановленої на цей день, Gerah потрапляє на депозит за довжиною мети: 1 за мету щонайменше 10 хвилин, 2 за щонайменше 20 хвилин, 3 за щонайменше 30 хвилин; мета в 5 хвилин нічого не дає. Не більше 3 gerah на день. Депозит переходить до твого гаманця, коли ти досягаєш денної мети 7 днів поспіль. Якщо ти пропускаєш день, депозит згорає, і 7 днів починаються знову. Gerah зберігається в гаманці застосунку PrepperPapa: за читання у Wordlight ти отримуєш її лише тоді, коли на твоєму пристрої встановлено застосунок PrepperPapa. Читання ранкового будильника теж зараховується.",
  "Napi Bibliaolvasás, heti céllal: minden nap, amikor eléred a napra beállított olvasási célodat (legalább {p} perc), 1 gerah kerül letétbe. A letét akkor kerül a tárcádba, ha {h} egymást követő napon eléred a napi célodat; ha egy nap kimarad, a letét elvész, és a {h} nap elölről indul. A reggeli ébresztős felolvasás is beleszámít.": "Щоденне читання Біблії з тижневою метою: кожного дня, коли ти досягаєш мети читання, встановленої на цей день (щонайменше {p} хвилин), 1 gerah потрапляє на депозит. Депозит переходить до твого гаманця, коли ти досягаєш денної мети {h} днів поспіль; якщо ти пропускаєш день, депозит згорає, і {h} днів починаються знову. Читання ранкового будильника теж зараховується.",
  "Ma {n} gerah-t letétbe helyeztünk. Heti cél: {k} / {h} nap.": "Сьогодні {n} gerah потрапило на депозит. Тижнева мета: {k} / {h} днів.",
  "Heti cél teljesítve: {n} gerah a tárcádba került!": "Тижневу мету досягнуто: {n} gerah перейшло до твого гаманця!",
  "heti bibliaolvasási cél": "тижнева мета читання Біблії",
  "Heti cél · Gerah-letét": "Тижнева мета · депозит Gerah",
  "Letétben: {n} gerah": "На депозиті: {n} gerah",
  "{k} / {h} nap egymás után": "{k} / {h} днів поспіль",
  "A {h}. egymást követő olvasott nap után a letét a tárcádba kerül.": "Після {h}-го дня читання поспіль депозит переходить до твого гаманця.",
  "Kimaradt egy nap: ez a letét elvész. A következő olvasott nappal a {h} nap elölről indul.": "День пропущено: цей депозит згорає. З наступного дня читання {h} днів починаються знову.",
