  "A Wordlightnak nincs tárcája. A Gerah-t a PrepperPapa alkalmazásban gyűjtheted be: telepítsd a PrepperPapát.": "У Wordlight немає гаманця. Gerah можна отримати в застосунку PrepperPapa: встановіть PrepperPapa.",
