  "Nincs megadva, ki érkezik ide.": "Не вказано, хто сюди прибуває.",
  "Kik érkeznek ide:": "Хто сюди прибуває:",
  "Mi van itt (nincs ide rendelt tétel)": "Що тут є (жодної позиції сюди не призначено)",
  "Sípolás": "Свисток",
