Object.assign(window.PP_FORD_SZOTAR.uk, {
  "A Gerah a közösségen belüli elszámolás egysége, nem pénz és nem fizetőeszköz. A PrepperPapa nem váltja át pénzre, nem garantálja az értékét, és nem részese a tagok közötti ügyleteknek. A tagok közötti vitákat és elszámolást a felhasználók egymás közt rendezik. Az offline fizetésnél előfordulhat, hogy ugyanazt a Gerah-t kétszer költik el; ennek kockázata a felhasználókat terheli.": "Gerah — одиниця взаєморозрахунків усередині спільноти, не гроші й не платіжний засіб. PrepperPapa не обмінює її на гроші, не гарантує її вартість і не є стороною угод між учасниками. Суперечки та розрахунки між учасниками користувачі вирішують між собою. Під час офлайн-платежів та сама Gerah може бути витрачена двічі; цей ризик несуть користувачі."
});
