  "Nincs elérhető Gerah-szoba: egy szoba gazdája kapcsolhatja be a szoba beállításaiban („Gerah-közösség”).": "Немає доступної кімнати Gerah: власник кімнати може ввімкнути це в налаштуваннях кімнати («Спільнота Gerah»).",
