 "Reggeli összefoglaló": "Ранкове зведення",
 "Minden reggel értesítés: a készlet hiányai, a készenléti szint, egy ige és egy felkészülési tanács. Ha megnyitod Noah-t, kártyaként is látod.": "Щоранку сповіщення: нестачі в запасах, рівень готовності, вірш із Біблії та порада з підготовки. Коли відкриєш Ноя, побачиш це і як картку.",
