 "A tipp a tudástárban": "Порада в базі знань",
 "A nap pályájához tudni kell, hol vagy: nyomd meg lent a „Mérés a helyzetemre” gombot.": "Для шляху сонця треба знати, де ти: натисни внизу «Вимір за моїм місцем».",
 "A nap most a horizont alatt van: a pályáját nappal rajzolom a képre.": "Сонце зараз під обрієм: його шлях малюється на зображенні вдень.",
 "A nap pályájához iránytű- és dőlésadat kell.": "Для шляху сонця потрібні дані компаса й нахилу.",
