 "A választ a telefonon futó gépi modell írja. Életveszélyben a forráscikket olvasd el, és hívd a 112-t. Az igét a Károli-fordításból az app illeszti be, nem a modell.": "Відповідь пише машинна модель, що працює на телефоні. У небезпеці для життя прочитай статтю-джерело й телефонуй на номер екстреної допомоги. Вірші вставляє застосунок зі свого перекладу Біблії, а не модель.",
 "Amit még tudjon rólad. Kérdezzben is mondhatod: „jegyezd meg, hogy …”": "Що ще йому знати про тебе. Можна сказати й у «Запитай»: «запам'ятай, що …»",
 "Az első használatkor a telefon még egyszer ennyi helyet foglal a gyorsabb futáshoz, tehát a letöltés méretének kétszerese kell szabadon.": "Під час першого використання телефон займає стільки ж місця ще раз для швидшої роботи, тож вільним має бути вдвічі більше, ніж розмір завантаження.",
 "Csak ezen a telefonon marad, sehova nem küldjük el. Gépelés közben magától mentődik.": "Залишається тільки на цьому телефоні й нікуди не надсилається. Зберігається само під час набору.",
