 "Mentett pontjaid ({db}):": "Твої збережені точки ({db}):",
 "A készletben ({db} tétel):": "У запасах ({db} предм.):",
 "… és még {n}": "… і ще {n}",
 "Ilyen tétel nincs a készletedben. (A készletben {db} tétel van.)": "Такого предмета немає у твоїх запасах. (У запасах {db} предм.)",
 "A készletedben {db} tétel van, összesen {ossz} darab. Kategóriánként:": "У твоїх запасах {db} предм., загалом {ossz} шт. За категоріями:",
