 "{nap} napos túra hátizsákkal": "{nap}-денний похід із рюкзаком",
 "{nap} napos út autóval": "{nap}-денна поїздка автомобілем",
 "{nap} napos út": "{nap}-денна подорож",
 "A Háztartásban még nincs családtag, ezért nem tudom kijelölni, kik mennek. A Mit vigyek? ablakot megnyitom, a napokat beállítottam ({nap}); a résztvevőket a Háztartás › Családtagok alatt vedd fel, utána a lista kiszámolja, mi kell.": "У домогосподарстві ще немає члена родини, тож я не можу вибрати, хто йде. Відкриваю вікно «Що взяти?» з налаштованими днями ({nap}); додай учасників у «Домогосподарство › Члени родини», і список порахує, що потрібно.",
 "Összeállítottam: {fej}, {fo} fő és {allat} állat ({nevek}). Megnyitom a Mit vigyek? ablakban, kitöltve; a listát ott látod és pipálhatod.": "Склав: {fej}, {fo} ос. і {allat} тварин ({nevek}). Відкриваю заповненим у вікні «Що взяти?»; там бачиш список і можеш відмічати.",
 "Összeállítottam: {fej}, {fo} fő ({nevek}). Megnyitom a Mit vigyek? ablakban, kitöltve; a listát ott látod és pipálhatod.": "Склав: {fej}, {fo} ос. ({nevek}). Відкриваю заповненим у вікні «Що взяти?»; там бачиш список і можеш відмічати.",
 "A Háztartásban csak {ossz} fő van, őket jelöltem ki. A hiányzó {hiany} főt vedd fel a Háztartásnál, hogy a lista velük is számoljon.": "У домогосподарстві лише {ossz} ос., їх я й вибрав. Додай відсутніх {hiany} ос. у домогосподарстві, щоб список їх теж урахував.",
 "A napok számát nem mondtad, {nap} nappal számoltam.": "Ти не сказав кількість днів, я рахував {nap} дн.",
 "Hová tervezzem az útvonalat? Írd meg a cél nevét (település, turistapont, saját pont vagy helyszín), például: „Tervezd meg az útvonalat Dobogókőre.”": "Куди спланувати маршрут? Напиши назву пункту призначення (населений пункт, туристична точка, збережена точка чи місце).",
 "Nem találom ezt a helyet: „{cel}”. Sem a saját pontjaid, sem a helyszíneid, sem a letöltött turistapontok, sem a települések között nincs ilyen nevű. Útvonalat fejből nem írok le; ha máshogy hívják, írd meg pontosabban, vagy a térképen egy pont buborékán válaszd az „Útvonal ide”-t.": "Не знаходжу цього місця: «{cel}». Такої назви немає ні серед твоїх точок, ні місць, ні завантажених туристичних точок, ні населених пунктів. Маршрут я ніколи не описую з пам'яті; якщо місце називається інакше, напиши точніше або на мапі вибери «Маршрут сюди» в бульбашці точки.",
 "Nem tudom, hol vagy (nincs GPS-helyzet), ezért a távolságot nem tudom megmondani.": "Не знаю, де ти (немає GPS-позиції), тому не можу сказати відстань.",
 "légvonalban {km} km, {egtaj} felé ({fok}°), {honnan} alapján.": "{km} км по прямій, на {egtaj} ({fok}°), за: {honnan}.",
