 "{db} tételnél nincs megadva lejárati dátum, ezeket nem tudom figyelni.": "{db} предм. не мають дати терміну, їх я не можу відстежувати.",
 "Nem tudom, hol vagy: nincs GPS-helyzet, mentett pont vagy otthon-koordináta, ezért a napkeltét nem tudom kiszámolni.": "Не знаю, де ти: немає GPS-позиції, збереженої точки чи координат дому, тому не можу обчислити схід сонця.",
