  "Mi a Gerah?": "Що таке Gerah?",
  "Ma kibányásztál {n} gerah-t!": "Сьогодні ви видобули {n} gerah!",
  "{n} perc · {g} gerah/nap": "{n} хв · {g} gerah/день",
  "Hogyan bányászhatsz Gerah-t?": "Як видобувати Gerah?",
  "Napi Bibliaolvasás: ha eléred a napra beállított célodat, a cél hossza szerint kapsz Gerah-t: legalább 10 perces cél után {a}, legalább 20 perces után {b}, legalább 30 perces után {c} gerah-t; az 5 perces cél után nem jár. Naponta legfeljebb {m} gerah (a reggeli ébresztő felolvasása is beleszámít).": "Щоденне читання Біблії: коли ви досягаєте мети, встановленої на день, ви отримуєте Gerah за довжиною мети: {a} за мету щонайменше 10 хвилин, {b} за щонайменше 20 хвилин, {c} gerah за щонайменше 30 хвилин; мета в 5 хвилин нічого не дає. Не більше {m} gerah на день (читання вголос ранкового будильника теж зараховується).",
  "Ajánlás: {n} gerah minden barátodért, aki aktiválja a profilját.": "Запрошення: {n} gerah за кожного друга, який активує профіль.",
  "Ha a barátod prémiumot vásárol: további {n} gerah ({d} nap után).": "Якщо друг купить преміум: ще {n} gerah (через {d} днів).",
  "Induló egyenleg: {n} gerah, egyszer.": "Стартовий баланс: {n} gerah, один раз.",
  "A napi Gerah-t a PrepperPapa alkalmazás adja:": "Щоденну Gerah дає застосунок PrepperPapa:",
  "Gerah-tárca létrehozása": "Створити гаманець Gerah",
  "Még nincs Gerah-tárcád, ezért nem kerül semmi letétbe.": "У тебе ще немає гаманця Gerah, тому на депозит нічого не потрапляє.",
  "A mai napért {n} gerah járna, de még nincs Gerah-tárcád, ezért nem került letétbe. Hozd létre a tárcádat mielőbb, hogy a mai nap is letétbe kerülhessen.": "За сьогоднішній день належало б {n} gerah, але в тебе ще немає гаманця Gerah, тому на депозит нічого не потрапило. Створи гаманець якнайшвидше, щоб і сьогоднішній день міг потрапити на депозит.",
  "Eddig összesen {n} gerah-t kaphattál volna a PrepperPapa alkalmazásban.": "Досі ти міг би отримати загалом {n} gerah у застосунку PrepperPapa.",
  "A mai napot a PrepperPapa alkalmazás veszi át, amikor legközelebb megnyitod. Ha a nap csatlakozik a heti cél egymást követő napjaihoz, {n} gerah kerül érte letétbe, és a heti cél teljesítésekor a tárcádba.": "Сьогоднішній день прийме застосунок PrepperPapa, коли ти наступного разу його відкриєш. Якщо день продовжує дні поспіль твоєї тижневої мети, за нього {n} gerah потраплять на депозит, а після виконання тижневої мети до твого гаманця.",
  "Ha ezen a telefonon telepíted, a telepítés napjától a Wordlightban teljesített napokat is átveszi: azokért, amelyek csatlakoznak a heti cél egymást követő napjaihoz, ott Gerah jár.": "Якщо встановиш його на цей телефон, то з дня встановлення він прийме й дні, виконані у Wordlight: за ті, що продовжують дні поспіль твоєї тижневої мети, отримаєш там Gerah.",
  "Wordlight — Biblia, internet nélkül is.": "Wordlight — Біблія, і без інтернету.",
  "A kód a fiókodhoz kötődik: lépj be, utána nyomd meg újra a Kód beváltása gombot.": "Код привʼязаний до твого облікового запису: увійди, потім знову натисни «Активувати код».",
  "A visszajelzés küldéséhez be kell lépned. Belépés után küldd el újra.": "Щоб надіслати відгук, потрібно увійти. Після входу надішли його ще раз.",
