// ===== 2026-11-01 prayer room: the 4-week cycle of 28 guided prayers + "Imádság a világért" (text: Énok; owner TG 32765-32783) =====
Object.assign(window.PP_FORD_SZOTAR.uk, {
  "Imádság a világért": "Молитва за світ",
  "Mind a 28 vezetett ima": "Усі 28 молитов з провідником",
  "{n}. hét": "Тиждень {n}",
  "Ezen a héten": "Цього тижня",
  "Négy hét, minden napra egy rövid vezetett ima, a kör négyhetente ismétlődik. Mindegyik hálaadással kezdődik, és csenddel zárul.": "Чотири тижні, на кожен день коротка молитва з провідником; цикл повторюється кожні чотири тижні. Кожна починається з подяки й завершується тишею.",
  "Megnyitás a térképen": "Відкрити на мапі",
  "A térkép világhelyzet-adatából, frissítve {kor}.": "З даних мапи про становище у світі, оновлено {kor}.",
  "Köszönd meg a hetet, ami mögötted van. Nevezz meg három konkrét dolgot, amiért hálás vagy.": "Подякуйте за тиждень, що минув. Назвіть три конкретні речі, за які ви вдячні.",
  "Uram, köszönöm a mögöttem lévő hetet, a jót is és azt is, amit még nem értek. Köszönöm, hogy nem engedted el a kezemet. Hálás vagyok azért a három dologért, amit most eléd hozok.": "Господи, дякую Тобі за тиждень, що минув, і за добре, і за те, чого я ще не розумію. Дякую, що Ти не відпустив моєї руки. Дякую Тобі за ті три речі, які я зараз приношу Тобі.",
  "Uram, voltak napok, amikor nélküled indultam, és nélküled döntöttem. Nem mentegetem magam, hanem eléd teszem. Köszönöm, hogy Jézusért megbocsátasz, és tisztán állhatok előtted.": "Господи, були дні, розпочаті без Тебе, і рішення, ухвалені без Тебе. Я не виправдовуюся, а кладу це перед Тобою. Дякую, що заради Ісуса Ти прощаєш, і я можу стояти перед Тобою з чистим серцем.",
  "Uram, te mondod: csendesedjetek. Elcsendesedek, és elismerem, hogy te vagy az Isten, nem én. Te vagy az, aki a zaj fölött is úr marad.": "Господи, Ти кажеш: затихніть. Я затихаю і визнаю, що Ти Бог, а не я. Ти Той, Хто залишається Господом і над усім шумом.",
  "Uram, eléd teszem a jövő hetet: a munkámat, a családomat és a döntéseket, amik várnak rám. Nem kérem, hogy minden könnyű legyen, azt kérem, hogy te vezess benne. Add, hogy felismerjem a hangodat, amikor szólsz.": "Господи, кладу перед Тобою наступний тиждень: мою роботу, мою родину і рішення, що на мене чекають. Не прошу, щоб усе було легко, прошу, щоб Ти вів мене в цьому. Дай мені впізнавати Твій голос, коли Ти говориш.",
  "Uram, itt vagyok. Nem mondok többet, csak előtted maradok.": "Господи, я тут. Більше нічого не кажу, просто залишаюся перед Тобою.",
  "Uram, mielőtt bármit kérnék, köszönöm, amit már adtál. Köszönöm az otthonomat, az erőmet és azokat az embereket, akik mellettem állnak. Nem magától értetődő, ajándék.": "Господи, перш ніж щось просити, дякую Тобі за те, що Ти вже дав. Дякую за мій дім, мої сили і за людей, які поруч зі мною. Це не само собою зрозуміле, це дар.",
  "Uram, voltak gondok, amiket úgy cipeltem, mintha te nem látnád. Bocsásd meg, hogy a félelmemnek jobban hittem, mint neked. Most leteszem őket a kezedbe.": "Господи, були турботи, які лежали на мені так, ніби Ти їх не бачиш. Пробач, що страх у мені брав гору над довірою до Тебе. Тепер я кладу їх у Твої руки.",
  "Uram, te nem azt mondod, hogy ne legyenek gondjaim, hanem hogy hozzam őket eléd. Imádsággal, kéréssel és hálával jövök, ahogy mondtad. Te békességet ígérsz, nem magyarázatot, és ez nekem elég.": "Господи, Ти не кажеш, що в мене не буде турбот, а велиш приносити їх до Тебе. Я приходжу з молитвою, проханням і подякою, як Ти сказав. Ти обіцяєш мир, а не пояснення, і мені цього досить.",
  "Uram, egyenként hozom eléd, ami ma a vállamon van. Mindegyiket rád bízom, nem azért, mert kicsik, hanem mert te nagy vagy. Őrizd meg a szívemet és a gondolataimat a Krisztus Jézusban.": "Господи, по одному приношу Тобі те, що сьогодні лежить на моїх плечах. Усе це довіряю Тобі, не тому, що це дрібниці, а тому, що Ти великий. Збережи моє серце і мої думки в Христі Ісусі.",
  "Uram, ami még bennem maradt, azt is tudod. Átadom szavak nélkül is.": "Господи, Ти знаєш і те, що ще залишилося в мені. Віддаю це Тобі навіть без слів.",
  "Uram, köszönöm, hogy nem azt kapom, amit megérdemlek, hanem kegyelmet. Köszönöm, hogy Jézus már megfizetett azért, amit én nem tudtam volna. Ezért jöhetek most eléd félelem nélkül.": "Господи, дякую, що отримую не те, на що заслуговую, а благодать. Дякую, що Ісус уже заплатив за те, що мені було б не під силу. Тому я можу зараз прийти до Тебе без страху.",
  "Uram, mutasd meg, mi az, amit rendbe kell tennem. Néven nevezem előtted, nem szépítem és nem magyarázom. Te hű és igaz vagy: megbocsátasz, és megtisztítasz minden hamisságtól.": "Господи, покажи мені, що я маю виправити. Називаю це перед Тобою прямо, не прикрашаю і не пояснюю. Ти вірний і праведний: Ти прощаєш і очищаєш від усякої неправди.",
  "Uram, a te szavad azt mondja: ha megvallom, megbocsátod. Nem a jó érzésemre építek, hanem a te hűségedre. Elfogadom, hogy ami megvallva van, az el is van rendezve.": "Господи, Твоє Слово каже: якщо я визнаю, Ти простиш. Я спираюся не на свої відчуття, а на Твою вірність. Приймаю, що визнане вже владнане.",
  "Uram, adj erőt, hogy ahol embertől kell bocsánatot kérnem, megtegyem. És adj szívet, hogy annak is megbocsássak, aki engem bántott. Tedd rendbe, amit én már nem tudok.": "Господи, дай мені сили попросити вибачення в людини там, де це потрібно. І дай мені серце, щоб пробачити й тому, хто завдав мені болю. Виправ те, що я вже не в силі виправити.",
  "Uram, tiszta lappal indulok. Köszönöm.": "Господи, починаю з чистого аркуша. Дякую.",
  "Uram, köszönöm a mai napot, a reggelt, az ételt az asztalon, a tetőt a fejem fölött. Köszönöm a kicsiket is, amiket észre sem veszek. Mindegyik tőled jött.": "Господи, дякую за сьогоднішній день, за ранок, за їжу на столі, за дах над головою. Дякую і за дрібниці, яких я навіть не помічаю. Усе це прийшло від Тебе.",
  "Uram, tudom, mi került az első helyre nálam az utóbbi időben, és az nem te voltál. Megvallom, hogy a figyelmemet és az időmet máshová adtam. Bocsáss meg, és segíts újra sorba rakni.": "Господи, я знаю, що останнім часом опинилося в мене на першому місці, і це був не Ти. Визнаю, що моя увага і мій час ішли деінде. Пробач і допоможи знову все розставити по порядку.",
  "Uram, te azt mondod: először az országodat és az igazságodat keressem. Nem arra kérsz, hogy ne dolgozzak, hanem hogy ne a gond vezessen. Segíts úgy élni, mintha hinném, hogy te viselsz rám gondot, mert hiszem.": "Господи, Ти кажеш: шукайте найперше Царства Божого і Його правди. Ти не просиш мене не працювати, а просиш, щоб мною не керувала тривога. Допоможи мені жити так, ніби я вірю, що Ти дбаєш про мене, бо я справді вірю.",
  "Uram, rakd rendbe a mai napom sorrendjét: te legyél az első, és minden más a helyére kerüljön. És eléd hozom a szükségleteimet is, mert te mondtad, hogy hozzam. Add meg, ami kell, és adj hálás szívet ahhoz, amit adsz.": "Господи, упорядкуй мій сьогоднішній день: будь Ти першим, а все інше нехай стане на своє місце. І приношу Тобі свої потреби, бо Ти сказав їх приносити. Дай те, що потрібно, і дай вдячне серце за те, що Ти даєш.",
  "Uram, a nap többi része a tiéd. Járj velem benne.": "Господи, решта дня належить Тобі. Іди зі мною в ній.",
  "Uram, köszönöm, hogy nem kell bejelentkeznem hozzád, és nem kell érdemet hoznom. Jézus miatt nyitva az út, és te nem fordulsz el. Köszönöm, hogy a trónod kegyelem trónja.": "Господи, дякую, що до Тебе не треба записуватися і не треба приносити заслуг. Завдяки Ісусові шлях відкритий, і Ти не відвертаєшся. Дякую, що Твій престол є престолом благодаті.",
  "Uram, amiben elbuktam, azt nem rejtem el előled. A szégyen azt mondja, hogy maradjak távol, de te azt mondod, hogy jöjjek közel. Jövök, és kérem az irgalmadat.": "Господи, своїх падінь я не приховую від Тебе. Сором каже мені триматися подалі, а Ти кажеш підійти ближче. Я приходжу і прошу Твоєї милості.",
  "Uram, te bizalommal hívsz, nem rettegéssel. Jézus tudja, milyen embernek lenni, ezért értesz engem. Alkalmas időben segítesz, és ez az idő most van.": "Господи, Ти кличеш мене з довірою, а не з острахом. Ісус знає, як це бути людиною, тому Ти розумієш мене. Ти допомагаєш вчасно, і цей час настав зараз.",
  "Uram, most nem magamért jövök, hanem másokért. Eléd hozom a családomat, név szerint, és a barátaimat. És eléd hozom azt az embert, akiről tudom, hogy most nehéz helyzetben van: légy közel hozzá, adj neki erőt és reményt, és használj engem, ha kell.": "Господи, зараз я приходжу не заради себе, а заради інших. Приношу Тобі свою родину, називаючи кожного на ім’я, і своїх друзів. І приношу Тобі ту людину, про яку знаю, що їй зараз важко: будь поруч із нею, дай їй сили й надію, і використай мене, якщо треба.",
  "Uram, itt maradok előtted. Elég, hogy te itt vagy.": "Господи, я залишаюся тут перед Тобою. Досить того, що Ти тут.",
  "Uram, ma a hálával kezdem, és nem sietek vele. Végigmegyek a héten, és köszönöm a jó pillanatokat egyiket a másik után: egy beszélgetést, egy elvégzett munkát, egy nyugodt estét. Te voltál mindegyikben, akkor is, ha nem vettem észre.": "Господи, сьогодні я починаю з подяки і не поспішаю. Проходжу весь тиждень і дякую Тобі за добрі моменти, один за одним: за розмову, за виконану роботу, за спокійний вечір. Ти був у кожному з них, навіть там, де мені цього не було видно.",
  "Uram, voltak percek a héten, amikor zúgolódtam, és a hiányra néztem, nem rád. Bocsásd meg, és változtasd meg a szívemet. Taníts hálásnak lenni akkor is, amikor nem könnyű.": "Господи, цього тижня були хвилини нарікання, коли мій погляд був на нестачі, а не на Тобі. Пробач і зміни моє серце. Навчи мене вдячності й тоді, коли нелегко.",
  "Uram, te azt mondod, mindenben adjak hálát, nem mindenért, hanem mindenben. A nehézben is te vagy velem, és ezért ott is van mit köszönnöm. Ez a te akaratod, és én ezt választom.": "Господи, Ти кажеш дякувати в усьому: не за все, а в усьому. І в тяжкому Ти зі мною, тому й там є за що дякувати. Така Твоя воля, і я обираю її.",
  "Uram, a hétvégét is veled szeretném tölteni, ne csak a hétköznapokat. Vigyázz azokra, akikkel együtt leszek, és add, hogy jó legyek hozzájuk. Legyen pihenés és öröm is benne.": "Господи, хочу провести з Тобою і вихідні, а не лише будні. Бережи тих, з ким я буду, і допоможи мені ставитися до них по-доброму. Нехай у цих днях будуть і відпочинок, і радість.",
  "Uram, örülök, hogy velem vagy. Csendben is ezt mondom.": "Господи, я радію, що Ти зі мною. Кажу це і в тиші.",
  "Uram, köszönöm, hogy ma meg lehet állni. Köszönöm, ami ezen a héten elkészült, és köszönöm, hogy nem rajtam múlik a világ. A pihenés is tőled jön.": "Господи, дякую, що сьогодні можна зупинитися. Дякую за те, що було завершено цього тижня, і дякую, що світ тримається не на мені. І відпочинок теж від Тебе.",
  "Uram, cipelek dolgokat, amiket nem rám bíztál. Felelősséget, amit te hordozol, aggodalmat, amit te már elrendeztél. Megvallom, hogy nehezen engedem el, és most leteszem.": "Господи, я несу те, чого Ти мені не доручав: відповідальність, яку несеш Ти, і тривогу про те, що Ти вже владнав. Визнаю, що мені важко це відпустити, і зараз кладу це перед Тобою.",
  "Uram, te a megfáradtakat hívod, és én fáradt vagyok. Nem azt kéred, hogy előbb rendbe jöjjek, hanem hogy jöjjek. Jövök hozzád, úgy, ahogy vagyok.": "Господи, Ти кличеш утомлених, і я серед них, я без сил. Ти не вимагаєш спершу дати собі лад, а просто кличеш прийти. Приходжу до Тебе як є.",
  "Uram, adj nyugalmat a testemnek és a lelkemnek. Ami a jövő héten vár, azt is a kezedbe teszem, hogy ne most hordozzam. Újítsd meg az erőmet, ahogy csak te tudod.": "Господи, дай спокій моєму тілу і моїй душі. Те, що чекає на мене наступного тижня, я теж кладу в Твої руки, щоб не нести цього зараз. Онови мої сили, як можеш лише Ти.",
  "Uram, megpihenek nálad. Nem teszek semmit, csak itt vagyok.": "Господи, я відпочиваю в Тебе. Нічого не роблю, просто я тут.",
  "Az Úr az én pásztorom": "Господь мій Пастир",
  "Köszönd meg, hogy van, aki vezet, és nem egyedül kell kitalálnod az utat.": "Подякуйте, що є Той, Хто веде, і вам не треба самотужки шукати дорогу.",
  "Uram, köszönöm, hogy nem egyedül kell kitalálnom, hová megyek. Te vezetsz, te gondoskodsz, és te ismered az utat, ahol én még nem jártam. Jó a te nyájadhoz tartozni.": "Господи, дякую, що мені не треба самотужки вирішувати, куди йти. Ти ведеш, Ти дбаєш, і Ти знаєш дорогу, ще не пройдену мною. Добре належати до Твоєї отари.",
  "Hol mentél a magad feje után a héten, ahelyett, hogy őt követted volna? Mondd el.": "Де цього тижня ви йшли власним шляхом замість того, щоб іти за Ним? Скажіть Йому.",
  "Uram, voltak helyek, ahová a magam feje után mentem, és nem kérdeztelek meg. Megvallom, hogy okosabbnak hittem magam a pásztoromnál. Hozz vissza, és én jövök.": "Господи, були шляхи, обрані мною на власний розсуд, без запитання до Тебе. Визнаю, що мені здавалося, ніби я знаю краще за свого Пастиря. Поверни мене, і я прийду.",
  "Olvasd el, és mondd ki saját szavaddal: ő az én pásztorom.": "Прочитайте і скажіть своїми словами: Він мій Пастир.",
  "Uram, te vagy az én pásztorom, nem általánosságban, hanem az enyém. Ha te vezetsz, nem szűkölködöm, mert te tudod, mi kell nekem. Erre építem ezt a hetet.": "Господи, Ти мій Пастир, не взагалі, а саме мій. Якщо Ти ведеш, я ні в чому не матиму нестачі, бо Ти знаєш, що мені потрібно. На цьому я будую цей тиждень.",
  "Kérd, hogy a jövő héten a hangját kövesd, és hogy a sötét völgyben is érezd, hogy ott van.": "Попросіть, щоб наступного тижня ви йшли за Його голосом і навіть у темній долині відчували, що Він поруч.",
  "Uram, add, hogy a jövő héten a te hangodat kövessem, ne a zajt. Ha völgybe vezet az út, add, hogy tudjam, ott is velem vagy. Legelőt és vizet is te adsz, rád bízom.": "Господи, допоможи мені наступного тижня йти за Твоїм голосом, а не за шумом. Якщо дорога поведе через долину, дай мені знати, що й там Ти зі мною. Пасовище й воду теж даєш Ти, я довіряю це Тобі.",
  "Maradj csendben, mint aki biztonságban van.": "Залишайтеся в тиші, як той, хто в безпеці.",
  "Uram, biztonságban vagyok nálad. Csendben maradok.": "Господи, у Тебе я в безпеці. Залишаюся в тиші.",
  "Elég a kegyelem": "Досить благодаті",
  "Köszönd meg azokat a helyzeteket, ahol a saját erőd nem volt elég, mégis átjutottál.": "Подякуйте за ті ситуації, де вашої власної сили не вистачило, але ви все ж пройшли крізь них.",
  "Uram, köszönöm azokat a helyzeteket, ahol a saját erőm elfogyott, és mégis átjutottam. Nem én voltam erős, te voltál. Köszönöm, hogy a gyengeségem nem akadály nálad.": "Господи, дякую за ті ситуації, де мої сили вичерпалися, і все ж мені вдалося пройти. Сила була не моя, а Твоя. Дякую, що моя слабкість для Тебе не перешкода.",
  "Hol próbáltad a saját erődből megoldani, amit rá kellett volna bíznod? Valld meg.": "Де ви намагалися власними силами розв’язати те, що треба було довірити Йому? Визнайте це.",
  "Uram, megvallom, hogy sokszor a magam erejéből akartam megoldani, amit neked kellett volna átadnom. Büszkeségből vagy félelemből, de nélküled. Bocsáss meg, és taníts rád támaszkodni.": "Господи, визнаю, що часто мені хотілося розв’язати власними силами те, що треба було віддати Тобі. З гордості чи зі страху, але без Тебе. Пробач і навчи мене спиратися на Тебе.",
  "Olvasd el. Figyeld meg: Pál nem a gyengeség megszűnését kapta, hanem a kegyelmet benne.": "Прочитайте. Помітьте: Павло отримав не звільнення від слабкості, а благодать у ній.",
  "Uram, te azt mondtad Pálnak: elég neked az én kegyelmem. Nekem is ezt mondod. Nem azt ígéred, hogy elveszed a tövist, hanem hogy az erőd a gyengeségemben teljesedik ki.": "Господи, Ти сказав Павлові: досить тобі Моєї благодаті. І мені Ти кажеш те саме. Ти не обіцяєш забрати колючку, а обіцяєш, що Твоя сила звершується в моїй немочі.",
  "Nevezd meg a gyenge pontodat erre a hétre, és kérd, hogy ott Krisztus ereje lakjon.": "Назвіть своє слабке місце на цей тиждень і попросіть, щоб там перебувала сила Христа.",
  "Uram, tudom, hol vagyok gyenge ezen a héten, és eléd hozom. Ott lakjon a Krisztus ereje, ahol az enyém nem elég. Nem kérem, hogy erős legyek, azt kérem, hogy te legyél erős bennem.": "Господи, я знаю, де моя слабкість цього тижня, і приношу її Тобі. Нехай там перебуває сила Христа, де моєї не вистачає. Не прошу сили для себе, прошу, щоб Ти був сильним у мені.",
  "Csendben hagyd, hogy a kegyelem elég legyen.": "У тиші дозвольте благодаті бути достатньою.",
  "Uram, elég nekem a kegyelmed. Ezt most elhiszem, és csendben maradok.": "Господи, мені досить Твоєї благодаті. Зараз я вірю в це і залишаюся в тиші.",
  "Ne félj": "Не бійся",
  "Köszönd meg azokat a pillanatokat, amikor féltél, és ő mégis ott volt.": "Подякуйте за ті моменти, коли вам було страшно, а Він усе одно був поруч.",
  "Uram, köszönöm azokat a pillanatokat, amikor féltem, és te mégis ott voltál. Köszönöm, hogy nem hagytál egyedül a félelemmel, akkor sem, amikor nem éreztelek. Visszanézve látom a kezedet.": "Господи, дякую за ті моменти, коли мені було страшно, а Ти все одно був поруч. Дякую, що не залишив мене наодинці зі страхом, навіть коли Твоя присутність не відчувалася. Озираючись назад, бачу Твою руку.",
  "A félelem gyakran olyan döntésekhez vezet, amiket nem vállalnánk tisztán. Hol döntöttél félelemből? Mondd el neki.": "Страх часто веде до рішень, яких ми не ухвалили б із чистим сумлінням. Де ви ухвалювали рішення зі страху? Скажіть Йому.",
  "Uram, megvallom, hogy voltak döntéseim, amiket a félelem hozott, nem a hit. Elhallgattam, elkerültem, halogattam, mert féltem. Bocsásd meg, és szabadíts meg a félelem uralmától.": "Господи, визнаю, що деякі мої рішення ухвалював страх, а не віра. Мовчання, ухиляння, зволікання: усе це було від страху. Пробач і визволи мене з-під влади страху.",
  "Olvasd el, és számold meg, hány ígéret van egy versben. Mindegyik a jelenlétéből fakad.": "Прочитайте й порахуйте, скільки обітниць в одному вірші. Кожна з них випливає з Його присутності.",
  "Uram, te azt mondod: ne félj, mert veled vagyok. Nem azt mondod, hogy nincs mitől, hanem hogy te ott vagy. Megerősítesz, megsegítesz, a jobboddal támogatsz, és én ebbe kapaszkodom.": "Господи, Ти кажеш: не бійся, бо Я з тобою. Ти не кажеш, що нема чого боятися, а кажеш, що Ти поруч. Ти зміцнюєш, допомагаєш, підтримуєш Своєю правицею, і я тримаюся за це.",
  "Nevezd meg a legnagyobb félelmedet most, és tedd mellé a vers szavait.": "Назвіть свій найбільший страх зараз і поставте поруч із ним слова вірша.",
  "Uram, kimondom előtted, mitől félek most a legjobban. Odateszem mellé a te szavaidat: veled vagyok, megerősítelek. Add, hogy a félelmem kisebb legyen, mint a hitem benned.": "Господи, я кажу перед Тобою, чого найбільше боюся зараз. І ставлю поруч Твої слова: Я з тобою, Я зміцню тебе. Нехай мій страх буде меншим за мою віру в Тебе.",
  "Maradj csendben, mint akit fog a jobb kéz.": "Залишайтеся в тиші, як той, кого тримає Божа правиця.",
  "Uram, te fogsz engem, nem én téged. Ebben nyugszom meg.": "Господи, це Ти тримаєш мене, а не я Тебе. У цьому я заспокоююся.",
  "Bízd rá az utadat": "Довір Господу свою дорогу",
  "Köszönd meg azokat a döntéseket, amiket utólag nézve ő igazgatott.": "Подякуйте за ті рішення, якими, як тепер видно, керував Він.",
  "Uram, köszönöm azokat a döntéseket, amikről utólag látom, hogy te igazgattad. Akkor nem értettem, most már igen. Köszönöm, hogy a kerülőutak is a te kezedben voltak.": "Господи, дякую за ті рішення, про які тепер бачу, що ними керував Ти. Тоді мені це було незрозуміло, а тепер зрозуміло. Дякую, що й обхідні шляхи були в Твоїх руках.",
  "Hol támaszkodtál csak a saját értelmedre, és hagytad ki őt a döntésből? Valld meg.": "Де ви покладалися лише на власний розум і не залучили Його до рішення? Визнайте це.",
  "Uram, megvallom, hogy voltak döntéseim, amikbe nem vontalak be. Mindent kiszámoltam, csak téged nem kérdeztelek meg. Bocsáss meg, és segíts bizalommal élni, ne csak okosan.": "Господи, визнаю, що були рішення, у яких для Тебе не знайшлося місця. Усе було прораховано, тільки Тебе ніхто не запитав. Пробач і допоможи мені жити з довірою, а не лише розумно.",
  "Olvasd el. Nem az értelmet tiltja, hanem azt, hogy csak arra építs.": "Прочитайте. Тут заборонено не розум, а опору лише на нього.",
  "Uram, te adtad az értelmemet, és nem kéred, hogy eldobjam. Azt kéred, hogy ne egyedül arra építsek, hanem rád. Minden utamon számolok veled, és te igazgatod az utamat.": "Господи, Ти дав мені розум і не просиш його відкинути. Ти просиш не спиратися лише на нього, а спиратися на Тебе. На всіх своїх дорогах я зважаю на Тебе, і Ти скеровуєш мою дорогу.",
  "Hozd eléje azt a döntést, ami most előtted áll. Kérj bölcsességet és nyitott szívet az ő irányára.": "Принесіть Йому рішення, яке стоїть перед вами зараз. Попросіть мудрості й відкритого серця для Його напрямку.",
  "Uram, eléd hozom azt a döntést, ami most előttem áll. Adj bölcsességet, és adj nyitott szívet, hogy a te irányodat elfogadjam akkor is, ha más, mint amit terveztem. Igazgasd ezt az utamat.": "Господи, приношу Тобі рішення, яке стоїть переді мною зараз. Дай мудрість і дай відкрите серце, щоб прийняти Твій напрямок, навіть якщо він не збігається з моїми планами. Скеруй цю мою дорогу.",
  "Csendben engedd el a kontrollt.": "У тиші відпустіть контроль.",
  "Uram, az utam a tiéd. Elengedem, és rád bízom.": "Господи, моя дорога належить Тобі. Відпускаю її і довіряю Тобі.",
  "Egymás terhét": "Носіть тягарі одне одного",
  "Köszönd meg azokat, akik a te terhedet hordozták, amikor nehéz volt.": "Подякуйте за тих, хто ніс ваш тягар, коли було важко.",
  "Uram, köszönöm azokat az embereket, akik hordozták a terhemet, amikor nehéz volt. Egy hívás, egy ima, egy segítő kéz, amikor kellett. Rajtuk keresztül te voltál ott.": "Господи, дякую за тих людей, які несли мій тягар, коли було важко. Дзвінок, молитва, рука допомоги, коли це було потрібно. Через них поруч був Ти.",
  "Kinek a terhe elől fordultál el az utóbbi időben, mert kényelmetlen volt? Mondd el.": "Від чийого тягаря ви останнім часом відвернулися, бо це було незручно? Скажіть Йому.",
  "Uram, megvallom, hogy volt valaki, akinek a terhe elől elfordultam, mert kényelmetlen volt. Láttam, és továbbmentem. Bocsásd meg, és adj szívet, ami nem fordul el.": "Господи, визнаю: була людина, чий тягар був мені незручний. Її потреба була в мене перед очима, але мені було зручніше пройти повз. Пробач і дай мені серце, яке не відвертається.",
  "Olvasd el. A Krisztus törvénye a szeretet: így teljesítjük be.": "Прочитайте. Закон Христа є любов: так ми його виконуємо.",
  "Uram, te azt mondod, hogy egymás terhét hordozzuk, és ezzel a Krisztus törvényét töltjük be. Nem szabály ez, hanem szeretet. Taníts úgy szeretni, ahogy te szerettél engem.": "Господи, Ти кажеш, щоб ми носили тягарі одне одного і так виконували закон Христа. Це не правило, а любов. Навчи мене любити так, як Ти полюбив мене.",
  "Nevezz meg három embert, akiknek most teher van a vállán. Imádkozz érte egyenként: egészségért, erőért, kiútért.": "Назвіть трьох людей, на чиїх плечах зараз тягар. Помоліться за кожного по черзі: про здоров’я, про силу, про вихід.",
  "Uram, eléd hozok három embert, akik most terhet hordoznak. Az elsőért kérem, hogy adj neki erőt, a másodikért, hogy gyógyítsd, a harmadikért, hogy mutass neki kiutat. És ha engem akarsz használni bármelyiküknél, mutasd meg, hogyan.": "Господи, приношу Тобі трьох людей, які зараз несуть тягар. За першого прошу: дай йому сили; за другого: зціли його; за третього: покажи йому вихід. І якщо Ти хочеш використати мене для когось із них, покажи як.",
  "Csendben kérdezd meg: kihez küld ma?": "У тиші запитайте: до кого Він посилає вас сьогодні?",
  "Uram, kihez küldesz ma? Csendben várom.": "Господи, до кого Ти посилаєш мене сьогодні? Чекаю в тиші.",
  "Ahogy ő megbocsátott": "Як Він простив",
  "Köszönd meg, hogy neked megbocsáttatott, konkrétan, nem általánosságban.": "Подякуйте, що вам прощено, конкретно, а не загалом.",
  "Uram, köszönöm, hogy megbocsátottál nekem. Nem általánosságban, hanem azt a konkrét dolgot is, ami most eszembe jut. Krisztusban elrendezted, és nem tartod számon.": "Господи, дякую, що Ти простив мене. Не загалом, а й ту конкретну річ, що зараз спадає мені на думку. У Христі Ти це владнав і більше не ставиш мені цього на рахунок.",
  "Kire haragszol még? Mondd ki a nevét Isten előtt, és valld meg, ha keserűséget hordozol.": "На кого ви ще гніваєтеся? Вимовте ім’я цієї людини перед Богом і визнайте, якщо носите в собі гіркоту.",
  "Uram, van valaki, akire még haragszom, és a nevét most kimondom előtted. Megvallom, hogy keserűséget hordozok, és ez nem tőled van. Vedd ki a szívemből, mert magam nem tudom.": "Господи, є людина, на яку я ще гніваюся, і зараз називаю її ім’я перед Тобою. Визнаю, що ношу в собі гіркоту, і вона не від Тебе. Вийми її з мого серця, бо власними силами я не можу.",
  "Olvasd el. A mérce: ahogy Isten Krisztusban nekem.": "Прочитайте. Мірило: як Бог у Христі простив вас.",
  "Uram, te azt mondod, úgy bocsássak meg, ahogy te megbocsátottál nekem Krisztusban. Ez a mérce, és én ebből élek. Nem azért bocsátok meg, mert a másik megérdemli, hanem mert én is kegyelmet kaptam.": "Господи, Ти кажеш прощати так, як Ти простив мене в Христі. Це мірило, і цим я живу. Я прощаю не тому, що інший на це заслуговує, а тому, що й мені дано благодать.",
  "Kérj erőt a megbocsátásra, és áldást arra az emberre. Ha túl nehéz, csak ezt mondd: segíts akarni.": "Попросіть сили пробачити і благословення для цієї людини. Якщо це надто важко, скажіть лише: допоможи мені захотіти.",
  "Uram, adj erőt, hogy megbocsássak annak, akit most eléd hoztam, és áldd meg őt. Ha még nem tudom teljesen, segíts akarni. Tedd meg bennem, amit én még nem tudok megtenni.": "Господи, дай мені сили пробачити тому, кого я зараз приношу Тобі, і благослови його. Якщо я ще не можу пробачити до кінця, допоможи мені захотіти. Зроби в мені те, чого я поки не в силі зробити.",
  "Csendben engedd el, ami a kezedben volt.": "У тиші відпустіть те, що тримали в руках.",
  "Uram, elengedem. A kezedbe teszem, nem az enyémben tartom.": "Господи, я відпускаю це. Кладу в Твої руки, а не тримаю у своїх.",
  "Megújuló erő": "Сила, що оновлюється",
  "Köszönd meg a hetet, és azt, hogy végigvitt rajta, akkor is, ha elfáradtál.": "Подякуйте за тиждень і за те, що Він провів вас крізь нього, навіть якщо ви втомилися.",
  "Uram, köszönöm, hogy végigvittél ezen a héten. Volt, hogy elfáradtam, de te nem fáradtál el mellettem. Köszönöm a mai napot, amikor meg lehet állni.": "Господи, дякую, що Ти провів мене крізь цей тиждень. Бувало, що сили закінчувалися, але Ти не втомлювався поруч зі мною. Дякую за сьогоднішній день, коли можна зупинитися.",
  "Hol pótoltad a saját erőddel azt, amit tőle kellett volna várnod? Mondd el.": "Де ви заповнювали власними силами те, чого треба було чекати від Нього? Скажіть Йому.",
  "Uram, megvallom, hogy sokszor a saját erőmből próbáltam pótolni azt, amit tőled kellett volna várnom. Hajtottam, mert nem bíztam. Bocsásd meg, és taníts várni rád.": "Господи, визнаю: надто часто мої власні сили займали місце того, чого треба було чекати від Тебе. Замість довіри були поспіх і напруження. Пробач і навчи мене чекати на Тебе.",
  "Olvasd el lassan. Az erő azoknak újul meg, akik benne bíznak, nem akik jobban igyekeznek.": "Прочитайте повільно. Сила оновлюється в тих, хто надіється на Нього, а не в тих, хто більше старається.",
  "Uram, te azt mondod, hogy akik benned bíznak, azok ereje megújul. Nem akik jobban igyekeznek, hanem akik bíznak. Én is ezt választom: nem több erőlködés, hanem több bizalom.": "Господи, Ти кажеш, що ті, хто надіється на Тебе, відновлять свою силу. Не ті, хто більше старається, а ті, хто довіряє. І я обираю це: не більше напруження, а більше довіри.",
  "Kérj megújulást a testednek, a gondolataidnak és a hitednek a jövő hétre.": "Попросіть оновлення для тіла, думок і віри на наступний тиждень.",
  "Uram, újítsd meg az erőmet a jövő hétre: a testemet, a gondolataimat és a hitemet. Add, hogy ne lankadjak meg a hosszú úton, és ne fáradjak el a mindennapiban. Te vagy a forrás, nem én.": "Господи, онови мої сили на наступний тиждень: моє тіло, мої думки і мою віру. Дай не ослабнути на довгій дорозі і не втомитися в буденному. Джерело Ти, а не я.",
  "Pihenj csendben, mint aki vár az Úrra.": "Відпочиньте в тиші, як той, хто чекає на Господа.",
  "Uram, várok rád. Csendben, nem sietve.": "Господи, я чекаю на Тебе. У тиші, не поспішаючи.",
  "Világosságom és üdvösségem": "Світло моє і спасіння моє",
  "Köszönd meg, hogy van világosságod, amikor minden más sötét.": "Подякуйте, що у вас є світло, коли все інше в темряві.",
  "Uram, köszönöm, hogy te vagy a világosságom, amikor körülöttem sötét van. Köszönöm, hogy az üdvösségem nem rajtam áll, hanem rajtad. Jó ezt egy vasárnap reggel kimondani.": "Господи, дякую, що Ти моє світло, коли довкола мене темно. Дякую, що моє спасіння залежить не від мене, а від Тебе. Добре сказати це в неділю зранку.",
  "Mitől remegtél a héten, ami nagyobbnak látszott, mint Isten? Valld meg.": "Перед чим ви тремтіли цього тижня, бо воно здавалося більшим за Бога? Визнайте це.",
  "Uram, megvallom, hogy voltak dolgok a héten, amik nagyobbnak látszottak, mint te. Remegtem tőlük, mintha te nem lennél az erősségem. Bocsáss meg, és állítsd helyre bennem az arányokat.": "Господи, визнаю, що цього тижня були речі, які здавалися більшими за Тебе. Вони змушували мене тремтіти, ніби Ти не моя твердиня. Пробач і віднови в мені правильні пропорції.",
  "Olvasd el, és válaszolj a kérdésre: kitől féljek?": "Прочитайте й дайте відповідь на запитання: кого мені боятися?",
  "Uram, te kérdezed: kitől féljek? És a válasz az, hogy senkitől, mert te vagy az életem erőssége. Nem azért, mert bátor vagyok, hanem mert a tiéd vagyok.": "Господи, Ти питаєш: кого мені боятися? І відповідь: нікого, бо Ти твердиня мого життя. Не тому, що в мені багато сміливості, а тому, що я належу Тобі.",
  "Kérd, hogy a jövő héten a te világosságában lásd a dolgokat, és hogy a házában lakjon a szíved.": "Попросіть, щоб наступного тижня ви бачили все в Його світлі і щоб ваше серце перебувало в Його домі.",
  "Uram, add, hogy a jövő héten a te világosságodban lássam a dolgokat, ne a félelem fényében. Legyen a szívem otthon nálad, akármerre jár a testem. Ezt kérem egyedül.": "Господи, дай мені наступного тижня бачити все в Твоєму світлі, а не у світлі страху. Нехай моє серце буде вдома в Тебе, куди б не йшло моє тіло. Тільки про це я прошу.",
  "Maradj csendben az ő világosságában.": "Залишайтеся в тиші в Його світлі.",
  "Uram, a világosságodban vagyok. Itt maradok.": "Господи, я у Твоєму світлі. Залишаюся тут.",
  "A Lélek gyümölcse": "Плід Духа",
  "Köszönd meg, hogy a Szentlélek benned lakik, és nem egyedül kell jóvá lenned.": "Подякуйте, що Святий Дух живе у вас і вам не треба самотужки ставати кращими.",
  "Uram, köszönöm, hogy a Szentlelked bennem lakik, és nem egyedül kell jóvá lennem. Köszönöm, hogy a változás nem az én görcsös igyekezetem, hanem a te munkád bennem.": "Господи, дякую, що Твій Святий Дух живе в мені і мені не треба самотужки ставати кращою людиною. Дякую, що зміна в мені не плід моїх судорожних зусиль, а Твоя праця в мені.",
  "A kilenc gyümölcsből melyik hiányzott a legjobban a hétvégén? Mondd el.": "Якого з дев’яти плодів вам найбільше бракувало на вихідних? Скажіть Йому.",
  "Uram, végignézem a Lélek gyümölcseit, és tudom, melyik hiányzott a hétvégén. Kimondom előtted, mi volt az. Bocsásd meg, és ne hagyd, hogy ez legyen a végső szó rólam.": "Господи, я переглядаю плоди Духа і знаю, якого бракувало на вихідних. Називаю перед Тобою, що це було. Пробач і не дай цьому стати останнім словом про мене.",
  "Olvasd el lassan a kilenc szót. Melyiket kéri tőled Isten ezen a héten?": "Прочитайте повільно дев’ять слів. Яке з них Бог просить у вас цього тижня?",
  "Uram, kilenc szót olvasok, és mindegyik a te természeted. Nem én termelem, a te Lelked termi bennem, ha vele járok. Mutasd meg, melyiket akarod ezen a héten növelni bennem.": "Господи, читаю дев’ять слів, і кожне з них про Твою природу. Не я їх виробляю, їх родить у мені Твій Дух, якщо я ходжу з Ним. Покажи, яке з них Ти хочеш виростити в мені цього тижня.",
  "Kérd azt az egy gyümölcsöt a hétre, és nevezd meg a helyzetet, ahol szükséged lesz rá.": "Попросіть на цей тиждень цей один плід і назвіть ситуацію, де він вам знадобиться.",
  "Uram, azt az egy gyümölcsöt kérem erre a hétre, amit most mutattál. Tudom, melyik helyzetben lesz rá szükségem, és eléd hozom azt is. Teremd meg bennem, amit én nem tudok előállítani.": "Господи, прошу на цей тиждень той один плід, який Ти зараз показав. Знаю, в якій ситуації він мені знадобиться, і приношу Тобі і її. Вирости в мені те, чого мені не створити власними силами.",
  "Csendben engedd, hogy a Lélek dolgozzon.": "У тиші дозвольте Духові діяти.",
  "Uram, dolgozz bennem. Nem állok az utadba.": "Господи, дій у мені. Я не стану Тобі на заваді.",
  "Gyors a hallásra": "Скорий на слухання",
  "Köszönd meg azokat, akik meghallgattak téged, és azt, hogy Isten mindig meghallgat.": "Подякуйте за тих, хто вислухав вас, і за те, що Бог завжди чує.",
  "Uram, köszönöm, hogy te mindig meghallgatsz, mielőtt szólnék. És köszönöm azokat az embereket, akik meghallgattak engem, amikor beszélnem kellett. A meghallgatás ajándék, és te adod.": "Господи, дякую, що Ти завжди чуєш мене, ще перш ніж я заговорю. І дякую за тих людей, які вислухали мене, коли мені треба було виговоритися. Коли тебе слухають, це дар, і даєш його Ти.",
  "Hol szóltál túl gyorsan, hol haragudtál túl hamar a héten? Nevezd meg az esetet, és valld meg.": "Де цього тижня ви заговорили надто швидко, де розгнівалися надто рано? Назвіть випадок і визнайте його.",
  "Uram, megvallom, hogy voltak percek, amikor gyorsabban szóltam, mint hallgattam, és hamarabb haragudtam, mint értettem. Egy konkrét eset most eszembe jut, és eléd teszem. Bocsásd meg, és adj szelíd nyelvet.": "Господи, визнаю, що були хвилини, коли мої слова випереджали слухання, а гнів випереджав розуміння. Зараз мені згадується один конкретний випадок, і я кладу його перед Тобою. Пробач і дай мені лагідний язик.",
  "Olvasd el a három sorrendet: gyors, késedelmes, késedelmes. Melyik a te gyenge pontod?": "Прочитайте три вказівки по черзі: швидкий, повільний, повільний. Яка з них ваше слабке місце?",
  "Uram, te azt kéred: gyors legyek a hallásra, késedelmes a szólásra és a haragra. Tudom, hol vagyok ebben gyenge. Taníts először téged hallgatni, aztán az embereket, és csak utána szólni.": "Господи, Ти просиш: будь швидкий до слухання, повільний до слова й повільний до гніву. Я знаю, де в цьому моя слабкість. Навчи мене спершу слухати Тебе, потім людей, і тільки потім говорити.",
  "Kérj türelmes szívet a mai beszélgetéseidhez, és egy konkrét emberhez, akivel nehezen beszélsz.": "Попросіть терплячого серця для сьогоднішніх розмов і для однієї конкретної людини, з якою вам важко говорити.",
  "Uram, adj türelmes szívet a mai beszélgetésekhez. Van valaki, akivel nehezen beszélek, őt külön eléd hozom: segíts meghallgatnom, mielőtt válaszolok. Legyen a szavam békesség, ne tűz.": "Господи, дай мені терпляче серце для сьогоднішніх розмов. Є людина, з якою мені важко говорити, і її я приношу Тобі окремо: допоможи мені вислухати, перш ніж відповісти. Нехай мої слова несуть мир, а не вогонь.",
  "Csendben hallgass, ez a gyakorlat maga.": "Слухайте в тиші, це і є сама вправа.",
  "Uram, hallgatlak. Most nem beszélek.": "Господи, я слухаю Тебе. Зараз я не говорю.",
  "Nézd a madarakat": "Погляньте на птахів",
  "Köszönd meg a mindennapi gondviselést: az ételt, a munkát, a hónap végéig kitartó erőt.": "Подякуйте за щоденне піклування: за їжу, за роботу, за сили, яких вистачило до кінця місяця.",
  "Uram, köszönöm a mindennapi gondviselésedet: az ételt az asztalon, a munkát, ami van, és az erőt, ami kitartott a hónap végéig. Nem magamnak köszönhetem, neked.": "Господи, дякую за Твоє щоденне піклування: за їжу на столі, за роботу, яка є, і за сили, яких вистачило до кінця місяця. Це не моя заслуга, а Твоя.",
  "Hol aggódtál a jövő miatt úgy, mintha az Atya elfelejtett volna? Mondd el.": "Де ви тривожилися про майбутнє так, ніби Отець забув про вас? Скажіть Йому.",
  "Uram, megvallom, hogy aggódtam a jövő miatt, mintha elfelejtettél volna. Számoltam, forgattam, nem aludtam, és közben nem néztem rád. Bocsásd meg a kishitűségemet.": "Господи, визнаю свою тривогу про майбутнє, ніби Ти забув про мене. Підрахунки, роздуми, безсонні ночі, і при цьому жодного погляду на Тебе. Пробач моє маловір’я.",
  "Olvasd el. Figyeld meg a kérdést a végén: nem vagytok-e sokkal különbek?": "Прочитайте. Помітьте запитання в кінці: чи ж ви не набагато кращі за них?",
  "Uram, te a madarakra mutatsz, és azt kérdezed, nem vagyok-e sokkal különb azoknál. A te gyermeked vagyok, nem csak a teremtményed. Ha őket eltartod, engem sem hagysz el.": "Господи, Ти вказуєш на птахів і питаєш, чи не набагато цінніше за них моє життя. Я Твоя дитина, а не лише Твоє творіння. Якщо Ти годуєш їх, то й мене не покинеш.",
  "Hozd eléje az anyagi és gyakorlati gondjaidat, egyenként, és kérd, hogy ő tartson el.": "Принесіть Йому свої матеріальні й практичні турботи, по одній, і попросіть, щоб Він забезпечив вас.",
  "Uram, eléd hozom az anyagi és gyakorlati gondjaimat, egyenként, ahogy vannak. Nem kérek fölösleget, azt kérem, hogy te tarts el, ahogy a madarakat. Adj munkát a kezemnek, és bizalmat a szívemnek.": "Господи, приношу Тобі свої матеріальні й практичні турботи, по одній, такими, якими вони є. Не прошу надлишку, прошу, щоб Ти годував мене, як годуєш птахів. Дай роботу моїм рукам і довіру моєму серцю.",
  "Csendben nézz ki az ablakon, vagy képzeld el: ő gondot visel.": "У тиші погляньте у вікно або уявіть: Він піклується.",
  "Uram, te gondot viselsz rám. Csendben ezt hagyom bennem leülepedni.": "Господи, Ти піклуєшся про мене. У тиші даю цьому осісти в мені.",
  "Imádság a vezetőkért": "Молитва за керівників",
  "Köszönd meg a békét, amiben élsz, a rendet, ami működik, és azokat, akik szolgálnak benne.": "Подякуйте за мир, у якому ви живете, за лад, який працює, і за тих, хто в ньому служить.",
  "Uram, köszönöm a békét, amiben élek, és a rendet, ami működik körülöttem, akkor is, ha nem tökéletes. Köszönöm azokat, akik ebben szolgálnak, az orvosokat, a tanárokat, a tisztviselőket. Rajtuk keresztül is gondot viselsz.": "Господи, дякую за мир, у якому живу, і за лад довкола мене, який працює, навіть якщо він не досконалий. Дякую за тих, хто в цьому служить: лікарів, учителів, службовців. Через них Ти теж піклуєшся.",
  "Hol ítéltél vagy szidtál vezetőket imádság helyett? Valld meg.": "Де ви засуджували або лаяли керівників замість молитви? Визнайте це.",
  "Uram, megvallom, hogy könnyebben szidtam a vezetőket, mint imádkoztam értük. Ítéltem ott, ahol könyörögnöm kellett volna. Bocsásd meg, és adj szívet, ami inkább kér, mint vádol.": "Господи, визнаю, що мені легше лаяти керівників, ніж молитися за них. Осуд був там, де треба було благати. Пробач і дай мені серце, яке радше просить, ніж звинувачує.",
  "Olvasd el. Mindenek előtt: ez a sorrend. És mindenkiért, nem csak azokért, akiket kedvelünk.": "Прочитайте. Насамперед: такий порядок. І за всіх, а не лише за тих, хто нам до вподоби.",
  "Uram, te azt kéred, hogy mindenekelőtt imádkozzak minden emberért, a vezetőkért is. Nem azért, mert egyetértek velük, hanem mert te így akarod. Ez nem politika, ez közbenjárás.": "Господи, Ти просиш насамперед молитися за всіх людей, і за керівників теж. Не через згоду з ними, а тому, що Ти так хочеш. Це не політика, це заступництво.",
  "Imádkozz a saját országod vezetőiért, a településedért, a gyülekezeted vezetőiért, és azokért, akik háborús országokban döntenek.": "Помоліться за керівників своєї країни, за своє місто чи село, за провідників своєї церкви і за тих, хто ухвалює рішення в країнах, де йде війна.",
  "Uram, eléd hozom azokat, akik az országomat vezetik, bármilyen oldalon állnak: adj nekik bölcsességet, igazságot és félelmet tőled. Imádkozom a településemért és azokért, akik ott döntenek. Imádkozom a gyülekezetem vezetőiért, hogy hűek maradjanak. És imádkozom azokért, akik háborús országokban döntenek életről és halálról: fordítsd a szívüket a béke felé.": "Господи, приношу Тобі тих, хто керує моєю країною, на якому б боці вони не стояли: дай їм мудрість, справедливість і страх Божий. Молюся за моє місто чи село і за тих, хто там ухвалює рішення. Молюся за провідників моєї церкви, щоб вони залишалися вірними. І молюся за тих, хто в країнах, де йде війна, вирішує питання життя і смерті: зверни їхні серця до миру.",
  "Csendben kérj békét, hogy nyugodalmas életet élhessünk.": "У тиші попросіть миру, щоб ми могли жити тихим і спокійним життям.",
  "Uram, adj békét, hogy csendes és nyugodalmas életet élhessünk. Ámen.": "Господи, дай мир, щоб ми могли провадити тихе й спокійне життя. Амінь.",
  "A reménység Istene": "Бог надії",
  "Péntek van, a hála napja. Köszönd meg a hét öt jó pillanatát, és köszönd meg a reménységet, ami nem tőled függ.": "Сьогодні п’ятниця, день подяки. Подякуйте за п’ять добрих моментів тижня і за надію, яка не залежить від вас.",
  "Uram, végigmegyek a héten, és megköszönöm az öt legjobb pillanatát, egyiket a másik után. És köszönöm, hogy a reménységem nem a körülményeimtől függ, hanem tőled. Te vagy a reménység Istene.": "Господи, проходжу весь тиждень і дякую за п’ять його найкращих моментів, один за одним. І дякую, що моя надія залежить не від обставин, а від Тебе. Ти Бог надії.",
  "Hol engedted el a reményt a héten, és hol lett belőle keserű beszéd? Mondd el.": "Де цього тижня ви відпустили надію і де вона перетворилася на гіркі слова? Скажіть Йому.",
  "Uram, megvallom, hogy voltak percek, amikor elengedtem a reményt, és keserű lett a beszédem. Nem hittem, hogy változhat bármi. Bocsásd meg, és töltsd meg újra a szívemet.": "Господи, визнаю, що були хвилини, коли надія вислизала з моїх рук і мої слова ставали гіркими. Не було віри, що щось може змінитися. Пробач і знову наповни моє серце.",
  "Olvasd el. Az öröm és a békesség a hitből jön, a reménység a Lélek erejéből.": "Прочитайте. Радість і мир приходять від віри, а надія від сили Духа.",
  "Uram, te a reménység Istene vagy, és örömmel, békességgel töltesz be a hitben. Nem én termelem a reményt, a Lelked adja. Hadd bővölködjek benne, ne csak megéljek.": "Господи, Ти Бог надії, і Ти наповнюєш мене радістю й миром у вірі. Не я виробляю надію, її дає Твій Дух. Дай мені рясніти нею, а не просто виживати.",
  "Kérj reménységet egy konkrét ügyben, ami most reménytelennek látszik.": "Попросіть надії в одній конкретній справі, яка зараз здається безнадійною.",
  "Uram, van egy ügy, ami most reménytelennek látszik, és eléd hozom. Adj reménységet benne, nem vak optimizmust, hanem a te Lelked erejét. Mutasd meg, hol vagy benne te.": "Господи, є одна справа, яка зараз здається безнадійною, і я приношу її Тобі. Дай мені надію в ній, не сліпий оптимізм, а силу Твого Духа. Покажи, де в цьому Ти.",
  "Csendben hagyd, hogy a béke betöltsön.": "У тиші дозвольте миру наповнити вас.",
  "Uram, töltsd be a szívemet békével. Csendben várom.": "Господи, наповни моє серце миром. Чекаю в тиші.",
  "Vizsgálj meg": "Досліди мене",
  "Köszönd meg, hogy Isten teljesen ismer, és mégis szeret.": "Подякуйте, що Бог знає вас повністю і все ж любить.",
  "Uram, köszönöm, hogy teljesen ismersz, a gondolataimat is, és mégis szeretsz. Előtted nem kell szerepet játszanom. Ez a legnagyobb nyugalom, ami egy hét végén létezik.": "Господи, дякую, що Ти знаєш мене повністю, навіть мої думки, і все ж любиш. Перед Тобою мені не треба грати роль. Це найглибший спокій, який тільки буває наприкінці тижня.",
  "Kérd, hogy ő mutassa meg, mit nem látsz magadban. Várj, és ami eszedbe jut, azt valld meg.": "Попросіть Його показати, чого ви не бачите в собі. Зачекайте, і те, що спаде на думку, визнайте.",
  "Uram, vizsgálj meg, és mutasd meg, mit nem látok magamban. Nem védekezem, várok. Ami most eszembe jut, azt megvallom, és kérem, hogy tisztítsd ki belőlem.": "Господи, досліди мене і покажи, чого я не бачу в собі. Я не захищаюся, я чекаю. Те, що зараз спадає мені на думку, я визнаю і прошу: очисти мене від цього.",
  "Olvasd el lassan. Ez egy bizalmi kérés: aki szeret, azt engedjük vizsgálni.": "Прочитайте повільно. Це прохання довіри: тому, хто любить, ми дозволяємо досліджувати нас.",
  "Uram, Dávid azt kérte, hogy vizsgáld meg, és én is ezt kérem. Nem félek a tekintetedtől, mert tudom, hogy szeretettel nézel. Vezess az örökkévalóság útján, ne csak a mai napon át.": "Господи, Давид просив Тебе дослідити його, і я прошу про те саме. Я не боюся Твого погляду, бо знаю, що Ти дивишся з любов’ю. Веди мене дорогою вічною, а не лише крізь сьогоднішній день.",
  "Kérd, hogy a jövő héten ott vezessen, ahol a legkönnyebb letérni.": "Попросіть, щоб наступного тижня Він вів вас там, де найлегше зійти з дороги.",
  "Uram, tudom, hol a legkönnyebb letérnem a jövő héten, és eléd hozom. Ott vezess, ott tarts meg. Add, hogy a szívem ne menjen oda, ahová a lábam már ne lépjen.": "Господи, я знаю, де наступного тижня мені найлегше зійти з дороги, і приношу це Тобі. Там веди мене, там утримай мене. Нехай моє серце не йде туди, куди моя нога вже не повинна ступати.",
  "Csendben hagyd, hogy ő nézzen rád, és pihenj ebben.": "У тиші дозвольте Йому дивитися на вас і відпочиньте в цьому.",
  "Uram, nézz rám. Én csendben maradok a tekinteted alatt.": "Господи, поглянь на мене. Я залишаюся в тиші під Твоїм поглядом.",
  "Hálaadással a kapuin": "Входьте в Його брами з подякою",
  "Vasárnap van. Lépj be hálával: köszönd meg, aki ő, nem csak azt, amit ad.": "Сьогодні неділя. Увійдіть з подякою: дякуйте за те, Ким Він є, а не лише за те, що Він дає.",
  "Uram, hálaadással lépek eléd ezen a reggelen. Köszönöm, aki vagy: hű, jó, irgalmas, a kezdettől a végig ugyanaz. Nem csak az ajándékaidat áldom, hanem a nevedet.": "Господи, цього ранку приходжу до Тебе з подякою. Дякую за те, Хто Ти є: вірний, добрий, милосердний, від початку до кінця той самий. Я благословляю не лише Твої дари, а й Твоє ім’я.",
  "Mi tart vissza attól, hogy teljes szívvel dicsérd? Mondd el neki.": "Що заважає вам славити Його всім серцем? Скажіть Йому.",
  "Uram, tudom, mi tart vissza attól, hogy teljes szívvel dicsérjelek. Fáradtság, sértődés, vagy egy el nem rendezett dolog. Eléd teszem, hogy ne álljon a kapuban.": "Господи, я знаю, що заважає мені славити Тебе всім серцем. Втома, образа чи щось невладнане. Кладу це перед Тобою, щоб воно не стояло в брамі.",
  "Olvasd el. Kapu, tornác, hála, dicséret: egyre közelebb visz hozzá.": "Прочитайте. Брами, подвір’я, подяка, хвала: усе ближче й ближче до Нього.",
  "Uram, te hívsz, hogy a kapuidon hálaadással, az udvarodba dicsérettel lépjek be. Minden lépés közelebb visz hozzád. Áldom a nevedet, mert te vagy az Isten.": "Господи, Ти кличеш мене входити в Твої брами з подякою, у Твої подвір’я з хвалою. Кожен крок наближає мене до Тебе. Благословляю Твоє ім’я, бо Ти Бог.",
  "Kérj a gyülekezetedért, a mai istentiszteletért, és azokért, akik ma nem tudnak eljönni.": "Помоліться за свою церкву, за сьогоднішнє богослужіння і за тих, хто сьогодні не може прийти.",
  "Uram, eléd hozom a gyülekezetemet és a mai istentiszteletet: szólj, és add, hogy halljuk. Imádkozom azokért, akik ma nem tudnak eljönni, mert betegek vagy távol vannak. Légy velük ott, ahol vannak.": "Господи, приношу Тобі свою церкву і сьогоднішнє богослужіння: говори, і дай нам почути. Молюся за тих, хто сьогодні не може прийти, бо вони хворі або далеко. Будь з ними там, де вони є.",
  "Maradj csendben az ő udvarában.": "Залишайтеся в тиші в Його подвір’ях.",
  "Uram, itt vagyok az udvarodban. Jó itt lenni.": "Господи, я тут, у Твоїх подвір’ях. Добре тут бути.",
  "Mint az Úrnak": "Як для Господа",
  "Köszönd meg a munkádat, azt is, ami fárasztó. Ez a hely, ahol szolgálhatsz.": "Подякуйте за свою роботу, і за ту, що втомлює. Це місце, де ви можете служити.",
  "Uram, köszönöm a munkámat, azt is, ami fárasztó és láthatatlan. Köszönöm, hogy van mit tennem, és van, aki számít rá. Ez a hely, ahol téged szolgálhatlak.": "Господи, дякую за мою роботу, і за ту, що виснажлива й непомітна. Дякую, що мені є що робити і є хтось, хто на це розраховує. Це місце, де я можу служити Тобі.",
  "Hol dolgoztál csak a látszatért, vagy csak félszívvel? Valld meg.": "Де ви працювали лише про людське око або впівсили? Визнайте це.",
  "Uram, megvallom, hogy voltak napok, amikor csak a látszatért dolgoztam, vagy félszívvel. Embereknek akartam megfelelni, nem neked. Bocsásd meg, és fordítsd a szívemet feléd a munkámban.": "Господи, визнаю, що були дні, коли моя робота була лише про людське око або впівсили. Мені хотілося догодити людям, а не Тобі. Пробач і зверни моє серце до Тебе в моїй роботі.",
  "Olvasd el. Mint az Úrnak: ez az egyetlen szó megváltoztatja a hétfőt.": "Прочитайте. Як для Господа: одна ця фраза змінює понеділок.",
  "Uram, amit ma teszek, azt neked teszem, nem embereknek. Ez a mondat megváltoztatja a hétfőmet. A legkisebb feladat is istentisztelet, ha neked végzem.": "Господи, те, що я роблю сьогодні, я роблю для Тебе, а не для людей. Ця фраза змінює мій понеділок. Навіть найменша справа стає поклонінням, якщо я виконую її для Тебе.",
  "Hozd eléje a hét munkáját, a nehéz feladatot, és azokat, akikkel dolgozol.": "Принесіть Йому роботу цього тижня, важке завдання і тих, з ким ви працюєте.",
  "Uram, eléd hozom a hét munkáját és azt a feladatot, ami a legnehezebb lesz. Adj hozzá erőt és tiszta szándékot. Áldd meg azokat, akikkel együtt dolgozom, és add, hogy jó legyen velem dolgozni.": "Господи, приношу Тобі роботу цього тижня і те завдання, яке буде найважчим. Дай для нього сили й чисті наміри. Благослови тих, з ким я працюю, і зроби так, щоб зі мною було добре працювати.",
  "Csendben ajánld fel a napot neki.": "У тиші присвятіть Йому цей день.",
  "Uram, ez a nap a tiéd. Lélekből, neked.": "Господи, цей день належить Тобі. Від душі, для Тебе.",
  "Békesség, amit a világ nem ad": "Мир, якого не дає світ",
  "Köszönd meg azt a békességet, amit megéltél, amikor emberileg nem volt rá ok.": "Подякуйте за мир, який ви пережили, коли по-людськи для нього не було причин.",
  "Uram, köszönöm azokat a pillanatokat, amikor békém volt, pedig emberileg nem volt rá ok. Az a te békességed volt, nem az enyém. Köszönöm, hogy nem a világtól függ.": "Господи, дякую за ті моменти, коли в мені був мир, хоча по-людськи для нього не було причин. Це був Твій мир, а не мій. Дякую, що він не залежить від світу.",
  "Mi nyugtalanítja a szívedet? Mondd el, és valld meg, ha a békességet máshol kerested: a kontrollban, a zajban, a menekülésben.": "Що непокоїть ваше серце? Скажіть Йому і визнайте, якщо шукали миру деінде: у контролі, у шумі, у втечі.",
  "Uram, megvallom, mi nyugtalanítja a szívemet, és azt is, hogy a békét máshol kerestem: a kontrollban, a zajban, a menekülésben. Nem tőled vártam. Bocsásd meg, és add vissza a békédet.": "Господи, визнаю, що непокоїть моє серце, і те, що мої пошуки миру йшли деінде: у контролі, у шумі, у втечі. Не від Тебе було моє очікування. Пробач і поверни мені Твій мир.",
  "Olvasd el. Nem úgy, ahogy a világ adja: ez a különbség.": "Прочитайте. Не так, як світ дає: у цьому різниця.",
  "Uram, te azt mondod, az én békességemet adom nektek, nem úgy, ahogy a világ adja. A világ békéje a baj hiánya, a tiéd a te jelenléted a bajban. Ezt kérem, nem a másikat.": "Господи, Ти кажеш: Мій мир даю вам, не так, як світ дає. Світ дає мир як відсутність біди, а Твій мир означає Твою присутність у біді. Про це я прошу, а не про інше.",
  "Kérd a békességét egy konkrét helyzetre, ami most feszültséget okoz.": "Попросіть Його миру для однієї конкретної ситуації, яка зараз викликає напруження.",
  "Uram, van egy helyzet, ami most feszültséget okoz, és eléd hozom. Add bele a te békességedet, amit nem lehet elvenni. Ne nyugtalankodjék a szívem, és ne féljen.": "Господи, є ситуація, яка зараз викликає напруження, і я приношу її Тобі. Вклади в неї Твій мир, якого не можна відібрати. Нехай моє серце не тривожиться і не боїться.",
  "Csendben fogadd el a békességét.": "У тиші прийміть Його мир.",
  "Uram, elfogadom a békességedet. Csendben maradok benne.": "Господи, я приймаю Твій мир. Залишаюся в ньому в тиші.",
  "Lámpás az úton": "Світильник на дорозі",
  "Köszönd meg, hogy van Igéd, és hogy olvashatod, hallgathatod, amikor akarod.": "Подякуйте, що у вас є Слово Боже і що ви можете читати й слухати його, коли захочете.",
  "Uram, köszönöm, hogy van Igéd, és hogy itt van nálam, olvashatom és hallgathatom, amikor akarom. Sokaknak ez nem adatott meg. Köszönöm, hogy szólsz rajta keresztül.": "Господи, дякую, що є Твоє Слово, і воно тут, зі мною, я можу читати й слухати його, коли захочу. Багатьом це не дано. Дякую, що Ти говориш через нього.",
  "Mikor tetted le az Igét, és indultál el a saját fényednél? Mondd el.": "Коли ви відкладали Слово і йшли при власному світлі? Скажіть Йому.",
  "Uram, megvallom, hogy sokszor letettem az Igédet, és a saját fényemnél indultam el. Aztán csodálkoztam, hogy sötét van. Bocsásd meg, és hozz vissza a lámpásodhoz.": "Господи, визнаю, що часто Твоє Слово в мене лежало осторонь, а дорогу освітлювало моє власне світло. А потім було здивування, чому так темно. Пробач і поверни мене до Твого світильника.",
  "Olvasd el. A lámpás a következő lépést mutatja, nem az egész utat.": "Прочитайте. Світильник показує наступний крок, а не всю дорогу.",
  "Uram, a te Igéd lámpás a lábamnak. Nem az egész utat mutatja, csak a következő lépést, és ez elég. Taníts megelégedni annyi fénnyel, amennyit ma adsz.": "Господи, Твоє Слово є світильником для моїх ніг. Воно показує не всю дорогу, а лише наступний крок, і цього досить. Навчи мене задовольнятися тим світлом, яке Ти даєш сьогодні.",
  "Kérd, hogy egy konkrét kérdésben az Igéből kapj irányt, és hogy legyen időd olvasni a héten.": "Попросіть, щоб в одному конкретному питанні ви отримали напрямок зі Слова і щоб цього тижня у вас був час читати.",
  "Uram, van egy kérdés, amiben irányt várok, és kérem, hogy az Igéden keresztül szólj bele. Adj időt és csendet a héten, hogy olvassalak, ne csak kapkodjak. Legyen a te szavad az első, amit meghallok.": "Господи, є питання, у якому я чекаю напрямку, і прошу Тебе промовити в ньому через Твоє Слово. Дай мені цього тижня час і тишу, щоб читати Тебе, а не лише поспішати. Нехай Твоє слово буде першим, що я почую.",
  "Csendben hagyd, hogy a világosság rád essen.": "У тиші дозвольте світлу впасти на вас.",
  "Uram, világíts az ösvényemre. Csendben követlek.": "Господи, освіти мою стежку. У тиші я йду за Тобою.",
  "Erősek az Úrban": "Зміцняйтеся в Господі",
  "Köszönd meg, hogy a harc már eldőlt a kereszten, és te az ő erejében állsz.": "Подякуйте, що битву вже вирішено на хресті і ви стоїте в Його силі.",
  "Uram, köszönöm, hogy a döntő harcot te már megnyerted a kereszten. Nem én harcolok a győzelemért, hanem a győzelemből állok meg. Köszönöm a fegyverzetet, amit nem én gyártottam.": "Господи, дякую, що вирішальну битву Ти вже виграв на хресті. Не я борюся за перемогу, я стою, спираючись на перемогу. Дякую за зброю, яку викувано не мною.",
  "Hol harcoltál emberek ellen, amikor nem ők voltak az igazi ellenség? Valld meg.": "Де ви боролися проти людей, коли справжнім ворогом були не вони? Визнайте це.",
  "Uram, megvallom, hogy emberek ellen harcoltam, pedig te azt mondod, nem test és vér ellen van a harcunk. Haraggal válaszoltam ott, ahol imádkozni kellett volna. Bocsásd meg, és nyisd meg a szememet.": "Господи, визнаю свою боротьбу проти людей, хоча Ти кажеш, що наша боротьба не проти тіла і крові. Моєю відповіддю був гнів там, де треба було молитися. Пробач і відкрий мені очі.",
  "Olvasd el. Erősek az Úrban, nem magunkban. Megállni, nem rohamozni.": "Прочитайте. Сильні в Господі, а не в собі. Встояти, а не йти на штурм.",
  "Uram, te azt mondod, legyek erős az Úrban, a te hatalmas erődben, nem a magaméban. Felöltözöm, amit adsz: az igazságot, a hitet, a békesség evangéliumát. Nem rohamozok, megállok.": "Господи, Ти кажеш мені зміцнюватися в Господі, у могутності Твоєї сили, а не своєї. Зодягаюся в те, що Ти даєш: у правду, у віру, у євангеліє миру. Я не йду на штурм, я стою.",
  "Imádkozz közbenjárva: a családodért, hogy megálljanak, a gyülekezetedért, a kísértésben lévő testvéredért, és az üldözött keresztényekért.": "Помоліться заступницькою молитвою: за свою родину, щоб вони встояли, за свою церкву, за брата чи сестру, які зараз у спокусі, і за переслідуваних християн.",
  "Uram, imádkozom a családomért, hogy megálljanak a hitben, és te őrizd őket. Imádkozom a gyülekezetemért, hogy egy legyen és erős. Eléd hozom azt a testvéremet, akiről tudom, hogy kísértésben van: tarts meg őt. És imádkozom az üldözött keresztényekért a világban, hogy hűek maradjanak, és te légy nekik pajzs.": "Господи, молюся за свою родину, щоб вони встояли у вірі, а Ти беріг їх. Молюся за свою церкву, щоб вона була єдиною і сильною. Приношу Тобі того з братів і сестер, про кого я знаю, що він зараз у спокусі: утримай його. І молюся за переслідуваних християн у всьому світі, щоб вони залишалися вірними, а Ти був для них щитом.",
  "Csendben állj meg az ő erejében.": "У тиші стійте в Його силі.",
  "Uram, a te erődben állok. Megállok, és te tartasz.": "Господи, я стою в Твоїй силі. Я стою, і Ти тримаєш мене.",
  "Minden reggel megújul": "Оновлюється щоранку",
  "A hála napja. Köszönd meg a hét minden reggelét, hogy felkelhettél, és azt, hogy ő minden reggel ugyanaz volt.": "День подяки. Подякуйте за кожен ранок тижня, за те, що ви могли встати, і за те, що Він щоранку був тим самим.",
  "Uram, köszönöm a hét minden reggelét, hogy felkelhettem, és hogy te minden reggel ugyanaz voltál. Köszönöm a kegyelmedet, ami nem fogyott el, pedig én sokszor elfogytam. Nagy a te hűséged.": "Господи, дякую за кожен ранок цього тижня, за те, що мені було дано встати, і за те, що щоранку Ти був тим самим. Дякую за Твою милість, яка не вичерпалася, хоча мої сили вичерпувалися так часто. Велика Твоя вірність.",
  "Hol kételkedtél a hűségében a héten, mert a körülmény mást mondott? Mondd el.": "Де цього тижня ви сумнівалися в Його вірності, бо обставини говорили інше? Скажіть Йому.",
  "Uram, megvallom, hogy voltak percek a héten, amikor a körülmény mást mondott, mint te, és én a körülménynek hittem. Kételkedtem a hűségedben. Bocsásd meg, te hű maradtál akkor is.": "Господи, визнаю, що цього тижня були хвилини, коли обставини говорили одне, а Ти інше, і мені вірилося обставинам. У мені був сумнів у Твоїй вірності. Пробач, Ти й тоді залишався вірним.",
  "Olvasd el. Ez a mondat romok közül hangzik, ezért igaz a te romjaid közt is.": "Прочитайте. Ці слова звучать серед руїн, тому вони правдиві і серед ваших руїн.",
  "Uram, ezt a mondatot valaki romok közt mondta ki, és azért igaz az én romjaim közt is. A te irgalmad nem fogyatkozik el, minden reggel megújul. Erre építem a következő reggelt is.": "Господи, ці слова хтось промовив серед руїн, і тому вони правдиві й серед моїх руїн. Твоє милосердя не вичерпується, воно оновлюється щоранку. На цьому я будую і наступний ранок.",
  "Kérd, hogy az ő hűsége legyen az, amire a hétvégén építesz, és nem a saját hangulatod.": "Попросіть, щоб на вихідних ви спиралися на Його вірність, а не на свій настрій.",
  "Uram, add, hogy a hétvégén a te hűségedre építsek, ne a hangulatomra. Újítsd meg a kegyelmedet a holnapi reggelre is, és add, hogy észrevegyem. Te vagy az, akiben nincs változás.": "Господи, допоможи мені на вихідних спиратися на Твою вірність, а не на свій настрій. Онови Твоє милосердя і на завтрашній ранок і дай мені це помітити. Ти Той, у Кому немає зміни.",
  "Csendben nyugodj meg a hűségében.": "У тиші заспокойтеся в Його вірності.",
  "Uram, nagy a te hűséged. Ebben nyugszom meg.": "Господи, велика Твоя вірність. У цьому я заспокоююся.",
  "Aki elkezdte, elvégzi": "Хто почав, Той і завершить",
  "Nézz vissza az elmúlt négy hétre. Köszönd meg, amit Isten elkezdett benned, akkor is, ha még nincs kész.": "Озирніться на останні чотири тижні. Подякуйте за те, що Бог почав у вас, навіть якщо це ще не завершено.",
  "Uram, visszanézek az elmúlt hetekre, és köszönöm, amit elkezdtél bennem. Nincs kész, de elkezdted, és ez a tiéd. Köszönöm, hogy nem hagytad abba, amikor én abbahagytam volna.": "Господи, озираюся на тижні, що минули, і дякую за те, що Ти почав у мені. Це не завершено, але Ти це почав, і це Твоє. Дякую, що Ти не покинув почате тоді, коли мені хотілося все покинути.",
  "Hol adtad fel magad, mintha a befejezés rajtad állna? Valld meg.": "Де ви махнули на себе рукою, ніби завершення залежить від вас? Визнайте це.",
  "Uram, megvallom, hogy voltak percek, amikor feladtam magamat, mintha a befejezés rajtam állna. Elfelejtettem, hogy a munka a tiéd. Bocsásd meg, és emeld fel újra a fejemet.": "Господи, визнаю, що були хвилини, коли мені здавалося, що зі мною все скінчено, ніби завершення залежить від мене. Забулося, що ця праця Твоя. Пробач і знову підніми мою голову.",
  "Olvasd el lassan. Aki elkezdte, az végzi el. Nem te.": "Прочитайте повільно. Хто почав, Той і завершить. Не ви.",
  "Uram, te kezdted el bennem a jó dolgot, és te végzed el a Krisztus Jézus napjáig. Nem én tartom magam a kezedben, te tartasz engem. Ebben a bizonyosságban zárom a hetet.": "Господи, Ти почав у мені добре діло і завершиш його до дня Христа Ісуса. Не я тримаю себе в Твоїх руках, Ти тримаєш мене. З цією певністю я завершую тиждень.",
  "Kérd, hogy a következő hetekben is folytassa benned a munkáját, és nevezd meg, hol szeretnél növekedni.": "Попросіть, щоб і наступними тижнями Він продовжував Свою працю у вас, і назвіть, у чому ви хотіли б зростати.",
  "Uram, folytasd bennem a munkádat a következő hetekben is. Tudom, hol szeretnék növekedni, és eléd hozom, de rád bízom, hogy mit és milyen sorrendben formálsz. A te időd a jó idő.": "Господи, продовжуй Свою працю в мені і наступними тижнями. Я знаю, у чому мені хочеться зростати, і приношу це Тобі, але довіряю Тобі, що і в якому порядку Ти формуватимеш. Твій час завжди слушний.",
  "Pihenj csendben abban, hogy Isten keze van rajtad, és ő nem engedi el.": "Відпочиньте в тиші в тому, що Божа рука на вас і Він не відпустить.",
  "Uram, a te kezed van rajtam, és te nem engedsz el. Csendben megpihenek ebben. Ámen.": "Господи, Твоя рука на мені, і Ти не відпустиш мене. У тиші я відпочиваю в цьому. Амінь.",
  "Most emeld fel a tekintetedet a saját ügyeidről a világra. Ezek az események most történnek, és ott emberek vannak.": "Тепер підніміть погляд від своїх справ на світ. Ці події відбуваються зараз, і там є люди.",
  "Uram, most nem magamért kérek, hanem azokért, akiket nem ismerek, de te igen. Eléd hozom a világ bajait, amik ma történnek.": "Господи, зараз я прошу не за себе, а за тих, кого я не знаю, але знаєш Ти. Приношу Тобі біди світу, що стаються сьогодні.",
  "Uram, te vagy a mi oltalmunk és erősségünk, bizonyos segítség a nyomorúságban. Hadd legyél az nekik is ma. Ámen.": "Господи, Ти наше пристановище й сила, певна допомога в біді. Будь цим і для них сьогодні. Амінь.",
  "Most nem tudjuk, mi történik épp a világban, de valahol most is baj van. Imádkozz azokért, akikről ma nem szól a hír.": "Зараз ми не знаємо, що саме відбувається у світі, але десь біда є і зараз. Помоліться за тих, про кого сьогодні не говорять у новинах.",
  "Uram, nem tudom, hol van ma a legnagyobb baj a világon, de te tudod. Eléd hozom azokat, akik ebben az órában földrengésben, árvízben, tűzben vagy háborúban vannak, és akikről nem szól a hír. Légy az oltalmuk, adj nekik segítséget és vigaszt, és fordítsd a világ szívét a béke felé. Te vagy a mi oltalmunk és erősségünk, bizonyos segítség a nyomorúságban. Ámen.": "Господи, я не знаю, де сьогодні у світі найбільша біда, але Ти знаєш. Приношу Тобі тих, хто в цю годину переживає землетрус, повінь, пожежу чи війну, і про кого не говорять у новинах. Будь їхнім пристановищем, дай їм допомогу й розраду і зверни серця народів до миру. Ти наше пристановище й сила, певна допомога в біді. Амінь.",
  // Imádság a világért, per event (Énok, ima-vilag-rovid.json, owner 2026-11-02 TG 33947-33954): encouragement + prayer, news labels
  "Amikor a föld megrendül, Isten nem rendül meg. Az imád most valódi kéz lehet a romok fölött.": "Коли земля хитається, Бог не хитається. Твоя молитва зараз може стати справжньою рукою над руїнами.",
  "A víz gyorsabb az embernél, de nem gyorsabb Istennél. Egy mondat most életet menthet.": "Вода швидша за людину, але не швидша за Бога. Одне речення зараз може врятувати життя.",
  "A tűz nem kérdez, de Isten hall. Állj oda imádságban azok mellé, akik most mindent hátrahagynak.": "Вогонь не питає, але Бог чує. Стань у молитві поруч із тими, хто зараз залишає все.",
  "Isten megígérte, hogy a víz nem lesz úr a földön. Kérd ezt most azoknak, akiknek mindent elvisz.": "Бог обіцяв, що вода не пануватиме над землею. Попроси про це зараз для тих, у кого вона забирає все.",
  "Jézus egy szóval elcsendesítette a vihart. Ugyanez a szó ma is érvényes, mondd ki értük.": "Ісус одним словом утихомирив бурю. Це слово чинне й сьогодні, промов його за них.",
  "A hegyek Isten kezében vannak. Imádkozz, hogy az emberek időben induljanak, és legyen hová menniük.": "Гори в Божій руці. Молися, щоб люди вирушили вчасно і мали куди йти.",
  "Az aszály csendes baj, ritkán szól róla a hír. Te most mégis eléje viheted Istennek.": "Посуха — тиха біда, про неї рідко пишуть у новинах. І все ж ти можеш зараз принести її до Бога.",
  "Jézus gyógyító keze ma sem rövidült meg. Állj oda a betegek és az ápolók mellé.": "Цілюща рука Ісуса й сьогодні не скоротилася. Стань поруч із хворими і з тими, хто їх доглядає.",
  "Isten nem áll be egyik tömegbe sem, mindkét oldalon az övéit látja. Imádkozz oldal nélkül, békéért.": "Бог не стає в жоден натовп, Він бачить Своїх з обох боків. Молися за мир, не стаючи на жоден бік.",
  "Boldogok a békességre igyekezők. Az imád ma ott lehet, ahová senki más nem jut el.": "Блаженні миротворці. Твоя молитва сьогодні може дістатися туди, куди більше ніхто не дістанеться.",
  "Uram, légy {hely} romjai alatt a várakozókkal, adj erőt a mentőknek, és vigasztald a gyászolókat.": "Господи, будь з тими, хто чекає під завалами в регіоні {hely}, дай сили рятувальникам і втіш тих, хто сумує.",
  "Uram, tartsd vissza a vizet, és vezesd időben magaslatra a part lakóit.": "Господи, стримай воду і вчасно виведи мешканців узбережжя на височину.",
  "Uram, védd meg {hely} menekülőit és tűzoltóit, és küldj esőt a lángokra.": "Господи, захисти тих, хто тікає, і пожежників у регіоні {hely} та пошли дощ на полум'я.",
  "Uram, őrizd meg {hely} lakóinak életét, és adj menedéket azoknak, akiknek otthona víz alatt áll.": "Господи, збережи життя людей у регіоні {hely} і дай притулок тим, чия домівка під водою.",
  "Uram, csendesítsd le a szelet és a vizet {hely} fölött, ahogy a tanítványaid hajóján tetted.": "Господи, вгамуй вітер і воду в регіоні {hely}, як Ти зробив це в човні Твоїх учнів.",
  "Uram, vezesd biztonságba {hely} lakóit, és adj bölcsességet azoknak, akik a kitelepítésről döntenek.": "Господи, виведи людей у регіоні {hely} у безпечне місце і дай мудрість тим, хто вирішує про евакуацію.",
  "Uram, adj esőt {hely} földjére és kenyeret az asztalukra, és nyisd meg a bővölködők kezét.": "Господи, дай дощ землі в регіоні {hely} і хліб на стіл її мешканців та відкрий руки тих, хто має в достатку.",
  "Uram, gyógyítsd {hely} betegeit, és adj erőt és védelmet az orvosoknak és ápolóknak.": "Господи, зціли хворих у регіоні {hely} і дай сили та захист лікарям і медсестрам.",
  "Uram, őrizd meg {hely} életeit mindkét oldalon, és fordítsd a szíveket a béke felé.": "Господи, збережи життя людей у регіоні {hely} з усіх боків і зверни серця до миру.",
  "Uram, védd meg {hely} civiljeit és gyermekeit, gyógyítsd a sebesülteket, és adj békét, bármelyik oldalon állnak.": "Господи, захисти мирних жителів і дітей у регіоні {hely}, зціли поранених і дай мир, на чиєму б боці вони не були.",
  "Érintett terület": "Уражена площа",
  "Legnagyobb szélsebesség": "Максимальна швидкість вітру",
  "Események": "Події",
  "Halálos áldozatok": "Загиблі",
  "Időszak": "Період",
  "Egy földrengés után órák döntenek életekről. Imádkozz a romok alatt lévőkért és a mentőkért.": "Після землетрусу від кількох годин залежать життя. Помоліться за тих, хто під завалами, і за рятувальників.",
  "Uram, eléd hozom {hely} területét, ahol megrendült a föld. Légy azokkal, akik a romok alatt várnak, és adj erőt és gyorsaságot azoknak, akik keresik őket. Vigasztald, aki ma elveszített valakit, és adj fedelet annak, akinek nem maradt.": "Господи, приношу Тобі край, де здригнулася земля: {hely}. Будь з тими, хто чекає під завалами, і дай сили й швидкості тим, хто їх шукає. Розрадь тих, хто сьогодні втратив когось із близьких, і дай прихисток тим, у кого його не лишилося.",
  "A tűz otthonokat, erdőket és életeket visz el. Imádkozz a menekülőkért és a tűzoltókért.": "Вогонь забирає домівки, ліси й життя. Помоліться за тих, хто тікає, і за пожежників.",
  "Uram, eléd hozom {hely} területét, ahol tűz pusztít. Védd meg azokat, akik menekülnek, és add, hogy mindenkit elérjen a figyelmeztetés időben. Adj erőt és védelmet a tűzoltóknak, és küldj esőt és szelet úgy, ahogy csak te tudod.": "Господи, приношу Тобі край, де лютує вогонь: {hely}. Захисти тих, хто тікає, і зроби так, щоб попередження вчасно дійшло до кожного. Дай силу й захист пожежникам і пошли дощ і вітер так, як можеш лише Ти.",
  "Az árvíz lassan jön, és mindent elvisz. Imádkozz azokért, akik az otthonukat látják eltűnni.": "Повінь приходить повільно і забирає все. Помоліться за тих, хто бачить, як зникає їхній дім.",
  "Uram, eléd hozom {hely} lakóit, akiket elért a víz. Őrizd meg az életüket, és adj menedéket azoknak, akiknek az otthona víz alatt áll. Légy a gyerekekkel és az idősekkel, akik nem tudnak maguktól menekülni, és adj türelmet és erőt a visszatéréshez.": "Господи, приношу Тобі мешканців краю, затопленого водою: {hely}. Збережи їхнє життя і дай притулок тим, чий дім під водою. Будь з дітьми й літніми людьми, які не можуть врятуватися самі, і дай терпіння й сили для повернення.",
  "A vihar előtt a várakozás, utána a kár. Imádkozz az útjában lévőkért.": "Перед бурею чекання, після неї руйнування. Помоліться за тих, хто на її шляху.",
  "Uram, eléd hozom {hely} területét, amerre a vihar tart vagy ahol már lecsapott. Csendesítsd a szelet és a vizet, ahogy a tanítványaid hajóján tetted. Védd meg azokat, akik az útjában állnak, és adj gyors segítséget, ahol a tetők és a falak már leomlottak.": "Господи, приношу Тобі край, куди йде буря або де вона вже вдарила: {hely}. Угамуй вітер і воду, як Ти зробив це в човні Твоїх учнів. Захисти тих, хто стоїть на її шляху, і пошли швидку допомогу туди, де дахи й стіни вже обвалилися.",
  "A hamu és a láva elől menekülni kell. Imádkozz a környék falvaiért és a kitelepítettekért.": "Від попелу й лави треба тікати. Помоліться за навколишні села і за евакуйованих.",
  "Uram, eléd hozom {hely} környékét, ahol a hegy kitört. Védd meg a falvakat és a városokat a láva és a hamu útjából, és adj bölcsességet azoknak, akik a kitelepítésről döntenek. Légy azokkal, akik mindent otthagytak, és adj nekik helyet, ahol megpihenhetnek.": "Господи, приношу Тобі край, де вивергається вулкан: {hely}. Захисти села й міста на шляху лави й попелу і дай мудрість тим, хто ухвалює рішення про евакуацію. Будь з тими, хто все залишив, і дай їм місце, де вони зможуть відпочити.",
  "Az aszály csendes katasztrófa, nincs hírverése. Imádkozz az éhezőkért és a földművesekért.": "Посуха: тиха катастрофа, про яку не галасують. Помоліться за голодних і за хліборобів.",
  "Uram, eléd hozom {hely} lakóit, ahol kiszáradt a föld, és nincs mit enni. Adj esőt a földre és kenyeret az asztalra, és nyisd meg azok kezét, akiknek bőven van. Tartsd meg a gyerekeket, és adj reményt a földműveseknek, akik újra vetnek.": "Господи, приношу Тобі мешканців краю, де висохла земля і нема що їсти: {hely}. Дай дощ землі й хліб на стіл і відкрий руки тих, у кого всього вдосталь. Збережи дітей і дай надію хліборобам, які знову сіють.",
  "A háborúban mindkét oldalon emberek halnak meg. Imádkozz a civilekért, a sebesültekért és a békéért, oldal nélkül.": "На війні гинуть люди по обидва боки. Помоліться за мирних жителів, за поранених і за мир, не обираючи сторони.",
  "Uram, eléd hozom {hely} területét, ahol fegyverek szólnak. Védd meg a civileket, a gyerekeket, az öregeket és azokat, akiknek nincs hová menniük. Gyógyítsd a sebesülteket, vigasztald a gyászolókat, és fordítsd a döntéshozók szívét a béke felé, bármelyik oldalon állnak. Te vagy a békesség Istene, hadd legyen béke ott is.": "Господи, приношу Тобі край, де лунає зброя: {hely}. Захисти мирних жителів, дітей, старих і тих, кому нема куди йти. Зціли поранених, розрадь тих, хто в жалобі, і зверни серця тих, хто ухвалює рішення, до миру, на якому б боці вони не стояли. Ти Бог миру, нехай мир прийде і туди.",
  "Ahol tömegek feszülnek egymásnak, ott félelem és harag van mindkét oldalon. Imádkozz békéért és józanságért, oldal nélkül.": "Там, де натовпи протистоять одне одному, страх і гнів є з обох боків. Помоліться за мир і розважливість, не обираючи сторони.",
  "Uram, eléd hozom {hely} területét, ahol feszültség és zavargás van az utcákon. Csendesítsd a haragot, és őrizd meg az életeket, azokét is, akik tüntetnek, és azokét is, akik rendet tartanak. Adj józanságot azoknak, akik döntenek, és add, hogy a sérelmek ne vérrel, hanem szóval oldódjanak meg.": "Господи, приношу Тобі край, де на вулицях напруження і заворушення: {hely}. Угамуй гнів і збережи життя, і тих, хто протестує, і тих, хто охороняє порядок. Дай розважливість тим, хто ухвалює рішення, і зроби так, щоб кривди розв’язувалися не кров’ю, а словом.",
  "A járványban a betegek és az ápolók egyformán kimerülnek. Imádkozz gyógyulásért és kitartásért.": "Під час епідемії і хворі, і медики однаково виснажуються. Помоліться за зцілення і витривалість.",
  "Uram, eléd hozom {hely} lakóit, ahol betegség terjed. Gyógyítsd a betegeket, és állítsd meg a terjedést, ahogy csak te tudod. Adj erőt és védelmet az orvosoknak és az ápolóknak, akik nem mennek haza, és vigasztald azokat, akik már elveszítettek valakit.": "Господи, приношу Тобі мешканців краю, де поширюється хвороба: {hely}. Зціли хворих і зупини поширення, як можеш лише Ти. Дай силу й захист лікарям і медсестрам, які не йдуть додому, і розрадь тих, хто вже втратив близьких.",
  "Nem tudjuk pontosan, mi történik ott, de Isten tudja. Imádkozz azokért, akik benne vannak.": "Ми не знаємо точно, що там відбувається, але Бог знає. Помоліться за тих, хто в цьому опинився.",
  "Uram, eléd hozom {hely} területét, ahol most baj van, és nem is tudom pontosan, milyen. Te tudod, és te látod minden embert ott. Légy velük, védd meg az életüket, és küldj segítséget időben.": "Господи, приношу Тобі край, де зараз біда, і я навіть не знаю точно, яка: {hely}. Ти знаєш і бачиш там кожну людину. Будь з ними, збережи їхнє життя і пошли допомогу вчасно.",
});

