// 2026-11-03: the guided prayer's encouragements (Énok, IMA_VEZ_BUZD; owner TG 34198) and the Charon voice's
// visible name (owner TG 34202-34212: Mihály, in each language its own form)
Object.assign(window.PP_FORD_SZOTAR.uk, {
  "A csend nem üresség, hanem jelenlét. Nem neked kell rendbe tenned a hetet, mielőtt Isten elé állsz: elég, ha megállsz. Ő a zaj fölött is Isten, és ma a te szívedben is az akar lenni.": "Тиша не порожнеча, а присутність. Тобі не треба впорядковувати свій тиждень, перш ніж стати перед Богом: досить зупинитися. Він Бог і над усяким шумом, і сьогодні Він хоче бути Богом і в твоєму серці.",
  "Az aggodalom mindig a holnapban él, a hála a mában. Amikor megköszönöd, amit már kaptál, a félelemnek kevesebb helye marad. Ma ne a terhet sorold elő először, hanem azt, amit Isten már megtett.": "Тривога завжди живе в завтрашньому дні, вдячність у сьогоднішньому. Коли ти дякуєш за те, що вже отримав, страхові лишається менше місця. Сьогодні перелічи спершу не свої тягарі, а те, що Бог уже зробив.",
  "Isten nem félig bocsát meg. Ha megvallottad, nem kell újra elővenned és újra hordoznod. Ma tiszta lappal indulsz, nem azért, mert jó voltál, hanem mert ő hű és igaz.": "Бог не прощає наполовину. Якщо ти це визнав, тобі не треба знову це діставати й знову нести. Сьогодні ти починаєш з чистого аркуша, не тому що був добрим, а тому що Він вірний і праведний.",
  "Ami először jön, az szabja meg a többit. Ha ma az ő országa kerül az első helyre, a teendőid nem tűnnek el, de a helyükre kerülnek. Bízd rá a sorrendet, és figyeld meg, mi adatik hozzá.": "Те, що стоїть першим, визначає все інше. Якщо сьогодні Його Царство посяде перше місце, твої справи не зникнуть, але стануть на своє місце. Довір Йому порядок і подивися, що додасться тобі.",
  "Nem kell kopogtatva, lehajtott fejjel jönnöd. A kegyelem trónja elé bizalommal járulhatsz, mert Jézus már kitárta az ajtót. Amire ma szükséged van, azt kérd bátran: ez a megfelelő idő.": "Тобі не треба несміливо стукати, похиливши голову. Ти можеш з відвагою приступити до престолу благодаті, бо Ісус уже широко відчинив двері. Про те, чого тобі треба сьогодні, проси сміливо: тепер слушний час.",
  "A hála nem a körülményekből fakad, hanem abból, aki a körülmények fölött áll. Nem mindenért, de mindenben adhatsz hálát. Ma keresd meg azt az egy pontot a nehézségben, ahol Isten keze már látszik.": "Вдячність народжується не з обставин, а з Того, Хто стоїть над ними. Не за все, але в усьому ти можеш дякувати. Сьогодні знайди в труднощах ту одну точку, де Божу руку вже видно.",
  "Jézus nem azt mondja, hogy előbb erősödj meg, és utána jöhetsz. A fáradtakat hívja. Tedd le nála, ami nyom, ne magyarázd, csak tedd le. A nyugalom nála kezdődik, nem a feladatok végén.": "Ісус не каже: спершу зміцнися, а тоді приходь. Він кличе струджених. Поклади перед Ним те, що тебе гнітить, не пояснюй, просто поклади. Спокій починається в Нього, а не наприкінці твоїх справ.",
  "Ha az Úr a pásztorod, nem egyedül kell kitalálnod az utat. Ő tudja, hol a legelő és hol a csendes víz. Ma ne a hiányt számold, hanem kövesd a hangját, és meglátod, hogy nem szűkölködsz.": "Якщо Господь твій пастир, тобі не треба самому шукати дорогу. Він знає, де пасовисько і де тихі води. Сьогодні не рахуй того, чого бракує, а йди за Його голосом, і побачиш, що ні в чому не будеш мати нестачі.",
  "A gyengeséged nem akadály Isten előtt, hanem tér, ahol az ő ereje megmutatkozik. Ma ne szégyelld, ahol kevés vagy. Pont ott mondja neked: elég az én kegyelmem.": "Твоя слабкість не перешкода перед Богом, а простір, де виявляється Його сила. Сьогодні не соромся того, в чому ти малий. Саме там Він каже тобі: Досить тобі Моєї благодаті.",
  "A félelem azt súgja, hogy egyedül vagy. Isten azt mondja: veled vagyok. Nem a félelem nagysága dönt, hanem az, hogy kinek a jobbja tart. Ma kapaszkodj abba a kézbe, ami nem enged el.": "Страх шепоче, що ти сам. Бог каже: Я з тобою. Вирішує не величина страху, а те, чия правиця тебе тримає. Сьогодні тримайся за руку, яка тебе не відпустить.",
  "Nem kell mindent értened ahhoz, hogy jó úton járj. Elég, ha minden lépésnél őt ismered el. A térkép nála van, neked a következő lépés jut. Tedd meg ma bizalommal.": "Не треба все розуміти, щоб іти правильною дорогою. Досить на кожному кроці пізнавати Його. Мапа в Нього, а тобі дано наступний крок. Зроби його сьогодні з довірою.",
  "Valaki ma nehezebb terhet visz, mint te. Lehet, hogy egy telefon, egy jó szó vagy egy ima az, ami könnyít rajta. Krisztus törvénye ilyen egyszerű lépésekben töltődik be. Kérdezd meg Istent: kinek kellek ma?": "Хтось сьогодні несе тягар важчий за твій. Можливо, дзвінок, добре слово чи молитва полегшать його. Закон Христовий виконується в таких простих кроках. Запитай Бога: кому я потрібен сьогодні?",
  "A megbocsátás nem azt jelenti, hogy nem fájt. Azt jelenti, hogy nem te viszed tovább a számlát. Ahogy Isten Krisztusban elengedte a tiédet, úgy engedheted el te is. Ma szabadabban léphetsz ki ebből az imából.": "Прощення не означає, що не було боляче. Воно означає, що ти більше не несеш цей рахунок далі. Як Бог у Христі простив тобі, так і ти можеш відпустити. Сьогодні ти можеш вийти з цієї молитви вільнішим.",
  "A kifáradás nem bukás. Aki az Úrban bízik, annak az ereje nem egyszer adatik, hanem újra és újra megújul. Ma nem kell repülnöd, ha csak járni tudsz. Ő ott is megtart, és nem fáradsz el.": "Втома не поразка. Тим, хто надіється на Господа, сила дається не один раз, вона відновлюється знову і знову. Сьогодні тобі не треба літати, якщо ти можеш тільки йти. Він підтримає тебе й там, і ти не втомишся.",
  "Ha az Úr a világosságod, a sötétség nem dönthet helyetted. Kitől féljek? Ez nem dac, hanem bizalom. Ma nézz szembe azzal, ami nyugtalanít, és mondd ki hangosan: az Úr az én életem erőssége.": "Якщо Господь твоє світло, темрява не може вирішувати за тебе. Кого буду боятися? Це не зухвалість, а довіра. Сьогодні подивися в обличчя тому, що тебе непокоїть, і скажи вголос: Господь твердиня життя мого.",
  "A Lélek gyümölcse nem erőfeszítésből terem, hanem abból, hogy közel maradsz hozzá. Nem neked kell előállítanod a békességet és a türelmet. Maradj ma a szőlőtőn, és a gyümölcs megjön.": "Плід Духа росте не з зусиль, а з того, що ти лишаєшся близько до Нього. Не тобі треба витворювати мир і терпеливість. Перебувай сьогодні у виноградині, і плід прийде.",
  "A legtöbb sebet nem a tett, hanem a gyors szó ejti. Ma figyelj egy kicsit tovább, mielőtt válaszolsz. Lehet, hogy a csendben meghallod, mit akar mondani a másik, és mit akar mondani Isten.": "Більшість ран завдає не вчинок, а поспішне слово. Сьогодні послухай трохи довше, перш ніж відповісти. Можливо, у тиші ти почуєш, що хоче сказати інший, і що хоче сказати Бог.",
  "A madarak nem aggódnak a holnapi kenyér miatt, mégis van mit enniük. Te sokkal értékesebb vagy előtte. Ma, amikor a gond megszólal, nézz fel egy pillanatra, és emlékezz: az Atya tud rólad.": "Птахи не журяться про завтрашній хліб, і все ж мають що їсти. Ти для Нього набагато цінніший за них. Сьогодні, коли озветься турбота, на мить підніми очі й згадай: Отець знає про тебе.",
  "A vezetőkért mondott ima nem politika, hanem szolgálat. Akár egyetértesz velük, akár nem, Isten kezében vannak. Imádkozz értük ma, hogy csendes és nyugodalmas életet élhessünk, te és a családod is.": "Молитва за правителів не політика, а служіння. Згоден ти з ними чи ні, вони в Божій руці. Помолися сьогодні за них, щоб ми провадили тихе й мирне життя, і ти, і твоя родина.",
  "A reménység nem azon múlik, mit látsz, hanem azon, kiben hiszel. Isten nem kis adagban adja, hanem bővölködni akar benned. Ma engedd, hogy a Szentlélek töltse be azt, ami kiürült.": "Надія залежить не від того, що ти бачиш, а від того, в Кого ти віриш. Бог дає її не малими порціями, а хоче, щоб ти збагатився нею. Сьогодні дозволь Святому Духові наповнити те, що спорожніло.",
  "Bátorság Istentől kérni, hogy vizsgáljon meg. Nem azért teszi, hogy elítéljen, hanem hogy vezessen. Ami ma előkerül, azt ne rejtsd el, add oda neki. Ő az örökkévalóság útjára akar vinni.": "Потрібна сміливість, щоб просити Бога випробувати тебе. Він робить це не для того, щоб осудити, а щоб вести. Те, що сьогодні вийде на світло, не ховай, віддай Йому. Він хоче провадити тебе дорогою вічною.",
  "A hálaadás a kapu, amin bejutsz az ő jelenlétébe. Nem kell nagy szavakat keresned. Kezdd azzal, ami ma eszedbe jut, és figyeld meg, hogyan nyílik meg a szíved a dicséretre.": "Подяка це брама, крізь яку ти входиш у Його присутність. Не треба шукати гучних слів. Почни з того, що сьогодні спадає на думку, і подивися, як твоє серце відкривається для хвали.",
  "Nincs olyan munka, ami túl kicsi ahhoz, hogy az Úrnak végezd. A mai feladataid, a rutin is, istentisztelet lehet. Tedd ma lélekből, mintha neki tennéd, mert valójában neki teszed.": "Немає роботи надто малої, щоб робити її для Господа. Твої сьогоднішні справи, навіть буденність, можуть бути служінням Богові. Роби їх сьогодні від душі, як для Нього, бо насправді ти робиш їх для Нього.",
  "A világ békessége a körülményektől függ, Jézusé nem. Ő úgy adja, hogy a vihar közepén is megmarad. Ma, ha a szíved nyugtalan, ne a vihar elcsendesedésére várj, hanem vedd át tőle a békességét.": "Мир цього світу залежить від обставин, мир Ісуса ні. Він дає його так, що він лишається й посеред бурі. Сьогодні, якщо твоє серце тривожиться, не чекай, поки вщухне буря, а прийми від Нього Його мир.",
  "Az ige nem reflektor, ami az egész utat bevilágítja, hanem lámpás a lábad elé. Elég a következő lépéshez. Ma ne a távoli kanyarokon aggódj, hanem tedd meg azt a lépést, amit most látsz.": "Слово не прожектор, що освітлює всю дорогу, а світильник для твоєї ноги. Його вистачає на наступний крок. Сьогодні не турбуйся про далекі повороти, а зроби той крок, який бачиш зараз.",
  "Az erő nem a te izmodból jön, hanem az ő hatalmából. Isten fegyverzete készen áll, csak fel kell öltened. Ma reggel tudatosan vedd magadra: az igazság, a hit, az ige ott van melletted.": "Сила приходить не з твоїх м'язів, а з Його могутності. Повна Божа зброя готова, треба лише зодягнутися в неї. Сьогодні вранці зодягнися в неї свідомо: правда, віра і Слово поруч із тобою.",
  "Bármi történt tegnap, ma reggel Isten irgalma újra friss. Nem fogyott el, nem kopott meg. Ez a nap új kezdet, mert nagy az ő hűsége, és nem a tiéd tartja meg a napot.": "Що б не сталося вчора, цього ранку Боже милосердя знову свіже. Воно не вичерпалося, не стерлося. Цей день новий початок, бо велика Його вірність, і не твоя вірність тримає цей день.",
  "Amit Isten elkezdett benned, azt nem hagyja félbe. Lehet, hogy most nem látod a végét, de ő látja. Ma nyugodj meg abban, hogy a munka az ő kezében van, és ő elvégzi.": "Те, що Бог почав у тобі, Він не залишить незавершеним. Можливо, зараз ти не бачиш кінця, але Він бачить. Сьогодні заспокойся в тому, що праця в Його руках, і Він її завершить.",
  "Mihály": "Михайло",
});

// fiok-mentes: account backup and restore (owner TG 34415, 2026-11-03)
Object.assign(window.PP_FORD_SZOTAR.uk, {
  "Mentés a fiókodba": "Резервна копія в обліковому записі",
  "Ha bekapcsolod, a teljes mentésedet (a készüléken tárolt adataidat, például jegyzeteket, kijelöléseket, könyvjelzőket, olvasási terveket és beállításokat) a fiókodba töltheted, egy általad választott mentési kulccsal titkosítva, és új telefonon ugyanazzal a fiókkal és kulccsal visszatöltheted.": "Якщо увімкнути, можна завантажити до облікового запису повну резервну копію (дані, що зберігаються на цьому пристрої, наприклад нотатки, виділення, закладки, плани читання та налаштування), зашифровану обраним вами ключем копії, і відновити її на новому телефоні з тим самим обліковим записом і ключем.",
  "Mentés a fiókba most": "Зберегти в обліковий запис зараз",
  "Visszatöltés a fiókból": "Відновити з облікового запису",
  "Automatikus mentés naponta": "Автоматична щоденна копія",
  "Naponta legfeljebb egyszer, csak ha változott valami. Ehhez a mentési kulcsból képzett kulcs ezen a készüléken marad, amíg be van kapcsolva; magát a mentési kulcsot nem tároljuk.": "Не частіше ніж раз на день і лише якщо щось змінилося. Для цього ключ, отриманий із ключа копії, залишається на цьому пристрої, поки функцію ввімкнено; сам ключ копії не зберігається.",
  "A fiókba mentéshez be kell jelentkezned.": "Щоб зберегти копію в обліковий запис, потрібно увійти.",
  "A fiókba mentés most nem érhető el, később próbáld újra.": "Збереження в обліковий запис зараз недоступне, спробуйте пізніше.",
  "A mentés túl nagy a fiókhoz ({m} MB, legfeljebb {max} MB). Készíts helyi teljes mentést fájlba.": "Копія завелика для облікового запису ({m} МБ, щонайбільше {max} МБ). Натомість зробіть локальну повну копію у файл.",
  "A fiókodban tárolt mentés: {t} ({m} MB).": "Копія в обліковому записі: {t} ({m} МБ).",
  "A fiókodban még nincs mentés ebből az alkalmazásból.": "У вашому обліковому записі ще немає копії з цього застосунку.",
  "Az automatikus mentés az első kézi mentés után indul.": "Автоматичне копіювання почнеться після першої ручної копії.",
  "A fiókodban már van egy mentés ({t}). Lecseréled erre? Az eddigi biztonsági példányként megmarad.": "В обліковому записі вже є копія ({t}). Замінити її цією? Поточна залишиться як страхувальна копія.",
  "Mentés megszakítva, nem töltöttünk fel semmit.": "Копіювання скасовано, нічого не завантажено.",
  "Feltöltés a fiókodba…": "Завантаження до облікового запису…",
  "Mentés feltöltve a fiókodba.": "Копію завантажено до вашого облікового запису.",
  "A fiókodban két mentés van: a legutóbbi ({a}) és az előző ({b}). Melyiket töltsük vissza?": "В обліковому записі дві копії: остання ({a}) і попередня ({b}). Яку відновити?",
  "A legutóbbit": "Останню",
  "Az előzőt": "Попередню",
  "A visszatöltés a készüléken levő adataidat felülírja a fiókban tárolt mentéssel ({t}). A mentési kulcs kell hozzá. Folytatod?": "Відновлення перезапише дані на цьому пристрої копією з облікового запису ({t}). Знадобиться ключ копії. Продовжити?",
  "Visszatöltve a fiókból. A nézetek frissülnek.": "Відновлено з облікового запису. Екрани оновлюються.",
  "Töröljük a fiókodból a tárolt mentéseidet is?": "Видалити також копії, що зберігаються у вашому обліковому записі?",
  "A fiókodban tárolt mentés törölve.": "Копію в обліковому записі видалено.",
});

// Igetanulmányozó: two translations side by side, Biblia prémium (owner TG 34609, 2026-11-03)
Object.assign(window.PP_FORD_SZOTAR.uk, {
  "Igetanulmányozó": "Вивчення віршів",
  "Igetanulmányozó ingyen naponta {db} fejezet, ma még {n}.": "Вивчення віршів безкоштовно {db} розділи на день, сьогодні залишилося {n}.",
  "Ma már {db} fejezetet összevetettél az igetanulmányozóban. Holnap újra jár; Biblia prémiummal korlátlanul összevetheted a fordításokat.": "Сьогодні ви вже порівняли {db} розділи у вивченні віршів. Завтра вони знову будуть; з Біблією Преміум ви порівнюєте переклади без обмежень.",
  "A két fordítás felcserélése": "Поміняти переклади місцями",
  "Előző fejezet": "Попередній розділ",
  "Következő fejezet": "Наступний розділ",
  "Ezt a fordítást most nem sikerült betölteni. Letöltés után internet nélkül is működik.": "Цей переклад зараз не вдалося завантажити. Після завантаження він працює і без інтернету.",
  "Válassz egy második fordítást az összevetéshez.": "Виберіть другий переклад для порівняння.",
  "A két fordítás más nyelvű: a szavak eltérését csak azonos nyelvű fordításoknál jelöljük.": "Переклади різними мовами: відмінні слова позначаються лише між перекладами однією мовою.",
  "A kiemelt szavak eltérnek a másik fordítástól.": "Виділені слова відрізняються від іншого перекладу.",
  "A második fordításban ez a könyv nincs meg.": "Цієї книги немає в другому перекладі.",
  "nincs megfelelő vers": "немає відповідного вірша",
  "Első fordítás": "Перший переклад",
  "Második fordítás": "Другий переклад",
  "Könyv": "Книга",
  "Két fordítás összevetése": "Порівняти два переклади",
  "Maradsz ennél a lépésnél · koppints a folytatáshoz": "Ви залишаєтеся на цьому кроці · торкніться, щоб продовжити",
  "Palackos víz (autó)": "Бутильована вода (авто)",
  "Energiaszelet (autó)": "Енергетичні батончики (авто)",
  "Powerbank (autó)": "Павербанк (авто)",
  "Powerbank (hétvégi ház)": "Павербанк (дача)",
  "Powerbank (rejtek)": "Павербанк (схованка)",
  "Gázpalack (rejtek)": "Газовий балон (схованка)",
  // Ujdonsagok v43.465 (2026-11-08)
  "Biblia: a Beállításokban választható az olvasási háttér: Csillagos ég, Statikus zöld, vagy 3D galaxis, amely a telefon döntésére mozog (szédülékenyeknek nem ajánlott; felolvasás közben áll).": "Біблія: у Налаштуваннях можна вибрати тло для читання: Зоряне небо, Статичний зелений або 3D-галактика, що рухається під час нахилу телефона (не рекомендовано тим, у кого легко паморочиться голова; під час читання вголос вона нерухома).",
  "Biblia: a könyvek között az apokrif könyvek polca alapból össze van csukva, egy koppintással kinyílik.": "Біблія: у списку книг полиця апокрифів типово згорнута; один дотик відкриває її.",
  "Biblia, lengyel UBG fordítás: a Prédikátor könyve és a Jelenések könyve rövidítése Kaz és Obj.": "Біблія, польський переклад UBG: Екклезіяст і Об'явлення тепер скорочуються як Kaz і Obj.",
  "Igekvíz és Igehely-párosító: felnőtt módban csak megjegyzésre érdemes igék jönnek (Zsoltárok, Példabeszédek, Jézus szavai, próféciák).": "Вікторина з віршів і Зіставлення посилань: у дорослому режимі трапляються лише вірші, які варто запам'ятати (Псалми, Приповісті, слова Ісуса, пророцтва).",
  "Vezetett ima: a felolvasott szöveg látható marad, és minden lépés megvárja, amíg a felolvasás véget ér.": "Ведена молитва: текст, що читається, залишається видимим, і кожен крок чекає, поки читання завершиться.",
  "Igetanuló: a nyomtatott vágási útmutató szerint minden csíkot a két vágójel között félúton kell elvágni.": "Вивчення віршів: друкована інструкція з різання тепер каже різати кожну смужку посередині між двома мітками.",
  "Gerah: tárca nélkül az app nem ígér letétet; a panel megmondja, hogy nincs tárca, és egy koppintással a tárcához visz. Az olvasási napok állapota a tárcával együtt átkerül a másik appba.": "Gerah: без гаманця застосунок більше не обіцяє депозит; панель повідомляє, що гаманця немає, і один дотик веде до гаманця. Стан днів читання переноситься в інший застосунок разом із гаманцем.",
  "Tablet: álló és fekvő elrendezés, a tablet elforgatható; a Biblia szövege kitölti a képernyőt, fekvő helyzetben a hivatkozások és jegyzetek oldalt nyílnak, és a kezdőlapon a világhelyzet csempéje jelenik meg.": "Планшет: вертикальне й горизонтальне розташування, планшет можна обертати; текст Біблії заповнює екран, у горизонтальному положенні посилання й нотатки відкриваються збоку, а на стартовій сторінці з'являється плитка про становище у світі.",
  "Világhelyzet térkép: új Támadás réteg, a terrortámadások és tömeges gyilkosságok is megjelennek a térképen és a vezetett ima világhelyzet-lépésében.": "Карта ситуації у світі: новий шар Теракт; теракти й масові вбивства тепер видно на карті та в кроці про світ у молитві з провідником.",
  "Megvallások: a Szellemi fegyverek felvétele megvallás mindenkinek beépítve, a fegyverzet minden darabjához saját képpel.": "Сповідання: сповідання «Одягнення духовної зброї» вбудоване для всіх, з окремим зображенням для кожної частини обладунку.",
  // t='attack' (TG 36837)
  "Terrortámadás / tömeges gyilkosság": "Теракт / масове вбивство",
  "Támadás": "Теракт",
  "Hírek alapján (48 óra):": "За новинами (48 годин):",
  "Közel van az Úr a megtört szívekhez. Állj most oda imádságban a gyászolók, a sebesültek és a mentők mellé.": "Близький Господь до зламаних серцем. Стань зараз у молитві поруч із тими, хто сумує, з пораненими та рятувальниками.",
  "Uram, vigasztald {hely} gyászolóit, gyógyítsd a sebesülteket, és ne engedd, hogy a gyűlölet mondja ki az utolsó szót.": "Господи, втіш тих, хто сумує в регіоні {hely}, зціли поранених і не дай ненависті сказати останнє слово.",
  // Névtelen statisztika (owner TG 36883, 2026-11-08, olvasas-stat.mjs)
  "Névtelen statisztika": "Анонімна статистика",
  "Ha bekapcsolod, egy nap végén az app egyetlen névtelen számsort küld: kerekítve hány percet olvastál és imádkoztál aznap, és melyik alkalmazásban. Nincs benne fiók, e-mail-cím és készülék-azonosító, az IP-címet sem tároljuk.": "Якщо ти це ввімкнеш, наприкінці дня застосунок надішле один анонімний набір чисел: скільки хвилин (заокруглено) ти читав Біблію й молився цього дня і в якому застосунку. У ньому немає облікового запису, адреси електронної пошти й ідентифікатора пристрою, IP-адресу ми теж не зберігаємо.",
  "Ebből csak napi összesítés készül (hányan olvastak és imádkoztak, átlagosan hány percet), amelyet a Wordlight oldalán közzéteszünk, de tíz főnél kisebb csoportot soha. A beküldött számsor nem köthető hozzád, ezért utólag nem törölhető; kikapcsolás után az app nem küld többet.": "З цього складаються лише щоденні підсумки (скільки людей читали й молилися, у середньому скільки хвилин), які ми публікуємо на сайті Wordlight, але ніколи для групи менше ніж десять осіб. Надіслані числа неможливо пов’язати з тобою, тому їх не можна видалити згодом; після вимкнення застосунок більше нічого не надсилає.",
});
// ===== 2026-11-08 local room mute (Boss TG 36904) =====
