  "A támogatás hamarosan elérhető.": "Підтримка незабаром буде доступна.",
  "Köszönjük, hogy használod az alkalmazást, és hogy gondolsz ránk.": "Дякуємо, що користуєшся застосунком і думаєш про нас.",
  "Köszönjük a támogatást!": "Дякуємо за підтримку!",
